const int MAXN=20005*20;
vector <int> e[10];
bool vis[MAXN],f[MAXN];
int g[MAXN];
int qid(int x,int op,int s,int t) {
	int id=(x-1)*2+op;
	for(int i=1;i<=9;++i) {
		id=id*3+(s>>i&1)+2*(t>>i&1);
	}
	return id;
}
int go(int s,int t) {
	int q=0;
	for(int i=1;i<=9;++i) if(!(s>>i&1)) {
		for(int j:e[i]) if(t>>j&1) q|=1<<i;
	}
	return q;
}
bool dp(int x,int op,int s,int t) {
	if(!t) return false;
	if(x==0) return true;
	int id=qid(x,op,s,t);
	if(vis[id]) return f[id];
	if(!op) {
		f[id]=true,vis[id]=true;
		for(int q=t;;q=(q-1)&t) {
			f[id]&=dp(x,1,s,t&q)||dp(x,1,s,t^(t&q));
			if(!f[id]) { g[id]=q; break; }
			if(!q) break;
		}
		return f[id];
	} else {
		f[id]=true,vis[id]=true;
		for(int i=1;i<=9;++i) if(!(s>>i&1)) {
			f[id]&=dp(x-1,0,s|1<<i,go(s|1<<i,t));
			if(!f[id]) { g[id]=i; break; }
		}
		return f[id];
	}
}
