void cdq(int l,int r) {
	if(l==r) return z+=(s[l]-s[l-1])>=w[l],void();
	int mid=(l+r)>>1;
	b[mid]=w[mid],b[mid+1]=w[mid+1];
	for(int i=mid-1;i>=l;--i) b[i]=max(w[i],b[i+1]);
	for(int i=mid+2;i<=r;++i) b[i]=max(w[i],b[i-1]);
	for(int i=mid,j=mid+1;i>=l;--i) {
		//s[j]>=b[i]+s[i-1]
		for(;j<=r&&b[j]<=b[i];++j) T.add(m+1-id[j]);
		int x=lower_bound(t+1,t+m+1,b[i]+s[i-1])-t;
		z+=T.qry(m+1-x);
	}
	T.init();
	for(int i=mid+1,j=mid;i<=r;++i) {
		//s[i]-b[i]>=s[j-1]
		for(;j>=l&&b[j]<b[i];--j) T.add(id[j-1]);
		int x=upper_bound(t+1,t+m+1,s[i]-b[i])-t-1;
		z+=T.qry(x);
	}
	T.init();
	cdq(l,mid),cdq(mid+1,r);
}
