ll modpow(ll x, ll n, ll p) {
    ll res = 1;
    while(n > 0) {
        if(n & 1) res = (res * x) % p;
        x = (x * x) % p;
        n /= 2;
    }
    return res;
}

ll modinv(ll x, ll p ) { return modpow(x, p - 2, p); }

