{
	int n=1<<__lg(a.size()+b.size()-2)+1;
	ntt(a,n,1);ntt(b,n,1);ll in=qpow(n,mod-2);
	for(int i=0;i<n;++i)a[i]=a[i]*b[i]%mod*in%mod;ntt(a,n,-1);
