void Cinit()
{
	ft[0]=ftv[0]=1;
	for(int i=1;i<N;++i)
	{
		ft[i]=ft[i-1]*i%mod;
		iv[i]=i==1?1:(mod-mod/i)*iv[mod%i]%mod;
		ftv[i]=ftv[i-1]*iv[i]%mod;
	}
}

