	d[q[++tl]=u]=d[fa]+1;
	axd=max(axd,d[u]);
	for(auto v:e[u])
		if(!vis[v]&&v!=fa)
		{
			d[v]=d[u]+1;
			getrt(v,u);
			sz[u]+=sz[v];
			ax=max(ax,sz[v]);
		}
	ax=max(ax,al-sz[u]);
	if(ax<=al/2)rt=u;
}
void sol(int u)
{
