const int N = 2005;
const ld inf = 1e18;

long long a[N * 2], b[N * 2];
ld f[N][N], g[N][N];

struct DP {
    long long pos[N];
    int d;
    ld dp[N];
    long long s[N];
    int l, r;

    void clear(int D) {
        l = 1, r = 0, d = D;
    }

    long long get(ld A, long long B, ld C, long long D) {
        long long L = max(B, D), R = 1e10, res = R + 1;
        if (A + hypot((ld)(L - B), (ld)d) <= C + hypot((ld)(L - D), (ld)d)) return L;
        if (A + hypot((ld)(R - B), (ld)d) > C + hypot((ld)(R - D), (ld)d)) return R + 1;
        while (L <= R) {
            long long mid = (L + R) >> 1;
            if (A + hypot((ld)(mid - B), (ld)d) <= C + hypot((ld)(mid - D), (ld)d)) {
                res = mid, R = mid - 1;
            } else {
                L = mid + 1;
            }
        }
        return res;
    }

    void append(ld val, long long S) {
        ld w;
        while (l + 1 <= r && pos[r - 1] >= (w = get(val, S, dp[r], s[r]))) {
            --r;
        }
        if (l == r) w = get(val, S, dp[r], s[r]);
        ++r, dp[r] = val, s[r] = S;
        if (l != r) pos[r - 1] = w;
    }

    ld query(long long x) {
        int w = upper_bound(pos + l, pos + r, x) - pos;
        return dp[w] + hypot((ld)(x - s[w]), (ld)d);
    }
} q1[N], q2[N];

