using f128 = long double;
constexpr f128 eps = 1e-9, alpha = 1e-5;
struct Point { f128 x, y; };
inline f128 norm(Point a) { return std::hypot(a.x, a.y); }
inline f128 angle(Point a) { return std::atan2(a.y, a.x) / std::acos(-1) * 180; }
inline Point operator + (Point a, Point b) { return {a.x + b.x, a.y + b.y}; }
inline Point operator - (Point a, Point b) { return {a.x - b.x, a.y - b.y}; }
inline Point operator * (Point a, f128 k) { return {a.x * k, a.y * k}; }
inline f128 operator * (Point a, Point b) { return a.x * b.x + a.y * b.y; }
inline f128 operator % (Point a, Point b) { return a.x * b.y - a.y * b.x; }
inline Point reflect(Point p, Point a, Point b) {
  f128 k = (p - a) * (b - a) / norm(b - a) / norm(b - a);
  Point h = a + (b - a) * k;
  return h * 2 - p;
}
inline void solve(int tt) {
  int n;
  scanf("%d", &n);
  std::vector<Point> P(n);
  for (auto &[x, y] : P)
    scanf("%Lf%Lf", &x, &y);
  Point O = P[0];
  for (int i = n - 1; i >= 2; i--)
    O = reflect(O, P[i - 1], P[i]);
  Point S = P[0], T = O;
  for (int i = 2; i <= n - 1; i++) {
    f128 den = (T - S) % (P[i] - P[i - 1]);
    if (std::abs(den) < eps)
      return puts("NO"), void();
    f128 u = ((P[i - 1] - S) % (T - S)) / den;
    if (u < alpha || 1.L - u < alpha)
      return puts("NO"), void();
    S = P[i - 1] + (P[i] - P[i - 1]) * u;
    T = reflect(T, P[i - 1], P[i]);
  }
  puts("YES");
  printf("%.10Lf\n", angle(O - P[0]));
}
int main() {
  int t;
  scanf("%d", &t);
  for (int tt = 1; tt <= t; tt++)
    solve(tt);
  return 0;
}

