void upd(int u,int l,int r,int L,int R,ll v){
	if(l>r||L>R) return;
	if(L<=l&&r<=R) return (void)(val[u]+=v,tag[u]+=v);
	pushdown(u);
	int m=(l+r)/2;
	if(L<=m) upd(u*2,l,m,L,R,v);
	if(R>m) upd(u*2+1,m+1,r,L,R,v);
	val[u]=min(val[u*2],val[u*2+1]);
