using namespace std;
typedef long long ll;
const int mod=998244353;
int n,q,a[200005],rt[200005],c[7000005][2],tot;
ll sum[7000005],prod[7000005],iprod[7000005];
int Power(int x,int y){
	int r=1;
	while(y){
		if(y&1)r=1ll*r*x%mod;
		x=1ll*x*x%mod,y>>=1;
	}
	return r;
}
void Ins(int &p,int q,int l,int r,int x){
	p=++tot;
	c[p][0]=c[q][0],c[p][1]=c[q][1],sum[p]=sum[q]+x;
	if(q)prod[p]=1ll*prod[q]*(x+1)%mod;
	else prod[p]=x+1;
	iprod[p]=Power(prod[p],mod-2);
	if(l==r)return ;
	int mid=(l+r)/2;
	if(x<=mid)Ins(c[p][0],c[q][0],l,mid,x);
	else Ins(c[p][1],c[q][1],mid+1,r,x);
}
int Find(int p,int q,int l,int r,ll K){
	if(l==r){
		if(!l)return 1;
		if(K>=sum[p]-sum[q])return 1;
		ll num=(sum[p]-sum[q])/l;
		ll vnum=K/l;
		return 1ll*(l+1-(K-vnum*l))*Power(l+1,num-vnum-1)%mod;
	}
	int mid=(l+r)/2;
	if(K>=sum[c[p][0]]-sum[c[q][0]]){
		return Find(c[p][1],c[q][1],mid+1,r,K-(sum[c[p][0]]-sum[c[q][0]]));
	}
	int res=1;
	if(c[p][1])res=1ll*res*prod[c[p][1]]%mod;
	if(c[q][1])res=1ll*res*iprod[c[q][1]]%mod;
	return 1ll*Find(c[p][0],c[q][0],l,mid,K)*res%mod;
}
int main(){
	scanf("%d%d",&n,&q);
	for(int i=1;i<=n;i++){
		scanf("%d",&a[i]);
		Ins(rt[i],rt[i-1],0,mod,a[i]-1);
	}
	for(int i=1;i<=q;i++){
		int l,r;
		ll K;
		scanf("%d%d%lld",&l,&r,&K);
		cout<<Find(rt[r],rt[l-1],0,mod,K)<<'\n';
	}
}

