        for (int d : adj[i])
            for (int dd : adj[i])
                if (d != dd)
                    for (int x : adj[d])
                        if (x != i && count(all(adj[dd]), x))
                            diag[i].push_back(x);
                            
        sort(all(diag[i]));
        diag[i].resize(unique(all(diag[i])) - diag[i].begin());
        if (sz(diag[i]) > 4) {
            cout << "NO\n";
            return;
        }
        // dbg(i, diag[i]);
    }
    
    vector <int> simple(n);
    
    vector <int> queue; int cur_s = 0;
    for (int i = 0; i < n; i ++)
        if (deg[i] == 1)
            queue.push_back(i);
    
    while (cur_s < sz(queue)) {
        int node = queue[cur_s ++];
        simple[node] = 1;
        for (int dest : adj[node])
            if (deg[dest] == 2 && !simple[dest])
                queue.push_back(dest);
    }
    
    dbg(simple);
    
    // right, up, left, down
    vector <pair <int, int>> moves = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    vector <pair <int, int>> moves2 = {{1, 1}, {-1, 1}, {-1, -1}, {1, -1}};
    
    pair <int, int> undef = make_pair(1 << 30, 1 << 30);
    vector <pair <int, int>> pos(n, undef);
    map <pair <int, int>, int> rev;
    
    map <int, int> miniX, maxiX, miniY, maxiY;
    
    vector <int> connected(n);
    
    vector <vector <int>> to_build(3);
    vector <int> deb(3);
    
    int starting = max_element(all(deg)) - deg.begin();
    
    auto build_node = [&](int node, int special = 0) -> int {
        //  1 -> success
        //  0 -> failure
        
        if (pos[node] != undef)
            return 1;
        dbg(node);
        
        vector <pair <int, int>> available;
        for (int d : diag[node])
            if (pos[d] != undef) {
                for (pair <int, int> dd : moves2)
                    if (!rev[pos[d] + dd])
                        available.push_back(pos[d] + dd);
                break;
            }
        
        if (available.empty())
            for (int d : adj[node]) {
                if (pos[d] != undef) {
                    for (pair <int, int> dd : moves)
                        if (!rev[pos[d] + dd])
                            available.push_back(pos[d] + dd);
                    break;
                }
            }
        
        if (node == starting)
            available.push_back(make_pair(0, 0));
        
        vector <pair <int, int>> options;
        
        for (pair <int, int> possible : available) {
            int good = 1;
            for (int d : adj[node])
                if (pos[d] != undef && dist(pos[d], possible) != 1)
                    good = 0;
            for (int d : diag[node])
                if (pos[d] != undef && dist(pos[d], possible) != 2)
                    good = 0;
            
            for (pair <int, int> dd : moves)
                if (good && rev[possible + dd] && !count(all(adj[node]), rev[possible + dd]     - 1))
                    good = 0;
            
            for (pair <int, int> dd : moves2)
                if (good && rev[possible + dd]) {
                    int found = 0;
                    int v = rev[possible + dd] - 1;
                    for (int d : adj[node])
                        if (count(all(adj[d]), v))
                            found = 1;
                    if (!found)
                        good = 0;
                }
            
            if (good) {
                if (miniX.find(possible.first) != miniX.end() && (possible.second < miniX[possible.first] - 1 || possible.second > maxiX[possible.first] + 1))
                    good = 0;
                if (miniY.find(possible.second) != miniY.end() && (possible.first < miniY[possible.second] - 1 || possible.first > maxiY[possible.second] + 1))
                    good = 0;
            }
            
            if (good) {
                if (special) {
                    options.push_back(possible);
                    continue;
                }
                rev[pos[node] = possible] = node + 1;
                if (miniX.find(possible.first) == miniX.end())
                    miniX[possible.first] = maxiX[possible.first] = possible.second;
                if (miniY.find(possible.second) == miniY.end())
                    miniY[possible.second] = maxiY[possible.second] = possible.first;
                
                miniX[possible.first] = min(miniX[possible.first], possible.second);
                maxiX[possible.first] = max(maxiX[possible.first], possible.second);
                miniY[possible.second] = min(miniY[possible.second], possible.first);
                maxiY[possible.second] = max(maxiY[possible.second], possible.first);
                for (int v : adj[node])
                    if (pos[v] == undef) {
                        connected[v] |= 1;
                        if (deg[v] <= 2 && diag[v].empty())
                            to_build[2].push_back(v);
                        else
                            to_build[connected[v] == 1].push_back(v);
                    }
                for (int v : diag[node])
                    if (pos[v] == undef) {
                        connected[v] |= 2;
                        to_build[connected[v] == 2].push_back(v);
                    }
                return 1;
            }
        }
        if (special)
            return sz(options);
        return 0;
    };

    auto build_all = [&]() -> int {
        to_build[0].push_back(starting);
        for (int i = 0; i < 3; i ++)
            if (deb[i] < sz(to_build[i])) {
                if (i == 2) {
                    int found = 0;
                    dbg(deb[i], to_build[i]);
                    vector <int> nv;
                    for (int j = deb[i]; j < sz(to_build[i]); j ++)
                        if (pos[to_build[i][j]] == undef)
                            nv.push_back(to_build[i][j]);
                    sort(all(nv));
                    nv.resize(unique(all(nv)) - nv.begin());
                    to_build[i] = nv;
                    deb[i] = 0;
                    dbg(nv);
                    if (sz(to_build[i]) - deb[i] > 4)
                        return 0;
                    
                    for (int v : to_build[i]) {
                        if (pos[v] == undef && build_node(v, 1) == 1) {
                            found = 1;
                            if (!build_node(v))
                                return 0;
                            break;
                        }
                    }
                    if (!found)
                        for (int v : to_build[i]) {
                            if (pos[v] == undef && !simple[v]) {
                                found = 1;
                                if (!build_node(v))
                                    return 0;
                                break;
                            }
                        }
                    if (!found)
                        for (int v : to_build[i])
                            for (int vv : to_build[i])
                                if (!found && v != vv)
                                    for (int a : adj[v])
                                        if (count(all(adj[vv]), a)) {
                                            found = 1;
                                            if (!build_node(v))
                                                return 0;
                                            break;
                                        }
                    if (!found)
                        if (!build_node(to_build[i][deb[i] ++]))
                            return 0;
                }
                else if (!build_node(to_build[i][deb[i] ++]))
                    return 0;
                i = -1;
            }
        return 1;
    };
    
    if (build_all()) {
        cout << "YES\n";
        for (pair <int, int> p : pos)
            cout << p.first << ' ' << p.second << '\n';
    }
    else
        cout << "NO\n";
    
    dbg(pos);
    
    return;
}

