int t,n,a[N],dp[N][N][2],f[N],g[N],siz[N];
vector<int> v[N];
void dfs(int u,int fa){
	vector<int> w;
	w.clear();
	siz[u]=1;
	for(auto i:v[u]){
		if(i==fa) continue;
		dfs(i,u);
		siz[u]+=siz[i];
		w.push_back(i);
	}
	for(int i=0;i<n;i++) dp[u][i][0]=inf;
	for(int i=0;i<n;i++){
		int sz=0;
		for(int j=0;j<=n;j++) f[j]=g[j]=inf;
		f[0]=0;
		for(auto j:w){
			for(int x=0;x<=sz;x++){
				g[x]=min(g[x],f[x]+dp[j][i+1][0]);
				for(int y=1;y<=siz[j];y++) g[x+y]=min(g[x+y],f[x]+dp[j][y][1]);
			}
			sz+=siz[j];
			for(int x=0;x<=sz;x++){
				f[x]=g[x];
				g[x]=inf;
			}
		}
		for(int l=0;l<=i;l++) dp[u][l][0]=min(dp[u][l][0],f[i-l]+a[u]*(i+1));
		dp[u][i+1][1]=f[i]+a[u]*(i+1);
	}
}
