const int N=2e6+5;
int tr[N],lz[N],a[N];
int x[N],y[N],ans[N];
int st[N],tp;
int n,m,q;
map<string,int> mp;
vector<array<int,2> > v[N];
void pushdown(int p){
	if(lz[p]){
		lz[lc(p)]^=lz[p];
		lz[rc(p)]^=lz[p];
		tr[lc(p)]=-tr[lc(p)];
		tr[rc(p)]=-tr[rc(p)];
		lz[p]=0;
	}
}
void pushup(int p){
	tr[p]=tr[lc(p)]+tr[rc(p)];
}
void update(int l,int r,int L,int R,int p){
	if(L<=l&&r<=R){
		tr[p]=-tr[p];
		lz[p]^=1;
		return;
	}
	int mid=(l+r)>>1;
	pushdown(p);
	if(L<=mid) update(l,mid,L,R,lc(p));
	if(mid<R) update(mid+1,r,L,R,rc(p));
	pushup(p);
}
void update2(int l,int r,int x,int v,int p){
	if(l==x&&r==x){
		tr[p]=v;
		return;
	}
	int mid=(l+r)>>1;
	pushdown(p);
	if(x<=mid) update2(l,mid,x,v,lc(p));
	else update2(mid+1,r,x,v,rc(p));
	pushup(p);
}
int query(int l,int r,int L,int R,int p){
	if(L<=l&&r<=R) return tr[p];
	int mid=(l+r)>>1,ans=0;
	pushdown(p);
	if(L<=mid) ans+=query(l,mid,L,R,lc(p));
	if(mid<R) ans+=query(mid+1,r,L,R,rc(p));
	pushup(p);
	return ans;
}
