		for(int i=1;i<=n*4;i++)mx[i]=make_pair(0,0),tg[i]=0;
	}
	inline void ad(int p,int z){tg[p]+=z,mx[p].fi+=z;}
	inline void pd(int p){
		if(tg[p])ad(p<<1,tg[p]),ad(p<<1|1,tg[p]),tg[p]=0;
	}
	inline void up(int p,int l,int r,int x,int y,int z){
		if(x<=l&&r<=y)return ad(p,z);
		int mi=(l+r)>>1;
		pd(p);
		if(x<=mi)up(p<<1,l,mi,x,y,z);
		if(y>mi)up(p<<1|1,mi+1,r,x,y,z);
		mx[p]=max(mx[p<<1],mx[p<<1|1]);
	}
	inline void up2(int p,int l,int r,int x,int z){
		if(l==r){mx[p]=make_pair(z,x);return;}
		pd(p);int mi=(l+r)>>1;
		if(x<=mi)up2(p<<1,l,mi,x,z);
		else up2(p<<1|1,mi+1,r,x,z);
		mx[p]=max(mx[p<<1],mx[p<<1|1]);
	}
	inline pi ask(int p,int l,int r,int x,int y){
		if(x<=l&&r<=y)return mx[p];
		pd(p);int mid=(l+r)>>1;pi mm=mp(-1,0);
		if(x<=mid)mm=max(mm,ask(p<<1,l,mid,x,y));
		if(y>mid)mm=max(mm,ask(p<<1|1,mid+1,r,x,y));
		return mm;
	}
