		if(p1<i)v0=T0.ask(1,1,m,p1+1,i);
		if(p0<i)v1=T1.ask(1,1,m,p0+1,i);
		if(v0>v1)dp[i]=v0.fi,pr[i]=mp(v0.se,0);
