	}
	vi Pl,Pr;
	for(int i=1;i<=m;i++){
		if(jc[i])Pr.pb(ft[i]);else Pl.pb(ft[i]);
		jc[i]+=jc[i-1];
	}
	vii Ql,Qr;
	for(pi t:qo){
		int lp=lo[t.fi],rp=ro[t.fi];
		if(lp>rp)continue;
		int st=t.se;
		if(jc[rp]-jc[lp-1]!=0)st|=2;
		if(st!=3)Ql.pb(mp(t.fi,st));
		st=t.se;
		if(jc[rp]-jc[lp-1]!=rp-lp+1)st|=1;
		if(st!=3)Qr.pb(mp(t.fi,st));
	}
	solp(l,M,Pl,Ql),solp(M+1,r,Pr,Qr);
}
