int n,m,z,a[N],ct[N],sc[3][N],pr[N],sm[N],st[20][N];

int sol()
{
	int i,j,ans=0;
	for(i=0;i<=4*n;++i)ct[i]=sm[i]=pr[i]=st[0][i]=0;
	for(i=1;i<=n;++i){++ct[a[i]];--ct[a[i]+m];}
	for(i=1;i<=4*n;++i)ct[i]+=ct[i-1];
	for(i=0;i<=4*n;++i)
		for(j=0;j<3;++j)
		{
			sc[j][i]=ct[i]==z+j-1;
			if(i)sc[j][i]+=sc[j][i-1];
		}
	for(i=m-1;i<=4*n;++i)
		pr[i]=max(i==m-1?-N:pr[i-1],sc[0][i]-(i>=m?sc[0][i-m]:0)-(
			sc[1][i]-(i>=m?sc[1][i-m]:0)
		));
	st[0][m-1]=sm[m-1]=0;
	for(i=m;i<=4*n;++i)
	{
		sm[i]=sm[i-1]+((ct[i]==z+1)-(ct[i]==z))+((ct[i-m]==z-1)-(ct[i-m]==z));
		st[0][i]=sm[i];
	}
	for(int k=1;(1<<k)<=4*n+1;++k)
		for(i=0;i+(1<<k)-1<=4*n;++i)
			st[k][i]=min(st[k-1][i],st[k-1][i+(1<<k-1)]);
	auto que=[](int l,int r){int k=__lg(r-l+1);return min(st[k][l],st[k][r-(1<<k)+1]);};
	for(i=1;i<=n;++i)
	{
		if(a[i]>=m)ans=max(ans,pr[a[i]-1]+(sc[2][a[i]+m-1]-sc[2][a[i]-1])-(sc[1][a[i]+m-1]-sc[1][a[i]-1]));
		ans=max(ans,sm[a[i]+m-1]-que(max(m-1,a[i]-1),a[i]+m-1));
	}
	return ans+sc[1][4*n];
}

