#include<bits/stdc++.h>
using namespace std;
#define PDI pair<double, int>

const int N = 310, M = 2 * N;
int n;
double f[N], g[N], ans;
struct tree
{
	int n, s;
	double dp[N], dp_f[N], dp_g[N], dp_ff[N], dp_gg[N];
	//level,probability and steps of reaching 1,probability and steps of reaching i(without 1)

	int h[N], ne[M], e[M], idx;
	void add(int a, int b)
	{
		e[++idx] = b, ne[idx] = h[a], h[a] = idx;
	}

	double f[N], g1[N], g2[N];//probability upward,steps upward,steps restart
	void dfs(int x, int fa)
	{
		f[x] = g1[x] = g2[x] = 0;
		if(dp[x] >= 0) return;

		int deg = 1;
		for(int i = h[x]; i; i = ne[i])
			if(e[i] != fa) dfs(e[i], x), deg++;
		if(!fa) return;

		for(int i = h[x]; i; i = ne[i])
			if(e[i] != fa)
			{
				f[x] += f[e[i]];
				g1[x] += f[e[i]] + g1[e[i]];
				g2[x] += 1 - f[e[i]] + g2[e[i]];
			}
		f[x] = 1 / (deg - f[x]);
		g2[x] = (g2[x] + g1[x] * (1 - f[x])) * f[x];
		g1[x] = (1 + g1[x] * f[x]) * f[x];
	}

	double maxn, ff, gg1, gg2;
	int maxid;
	void dfs1(int x, int fa, double f0, double g01, double g02)
	{
		if(dp[x] >= 0) return;
		if(fa)
		{
			g01 = g01 * f[x] + g1[x] * f0;
			g02 = g02 * f[x] + g1[x] * (1 - f0) + g2[x];
			f0 *= f[x];
		}

		double res = (g01 + g02) / f0;
		if(res > maxn) maxn = res, maxid = x;
		if(x == s) ff = f0, gg1 = g01, gg2 = g02;
		for(int i = h[x]; i; i = ne[i])
			if(e[i] != fa) dfs1(e[i], x, f0, g01, g02);
	}

	vector<int> rk;
	void init()
	{
		scanf("%d%d", &n, &s);
		for(int i = 1, a, b; i < n; i++)
			scanf("%d%d", &a, &b), add(a, b), add(b, a);

		for(int i = 1; i <= n; i++) dp[i] = -1;
		for(int i = 1; i < n; i++)
		{
			dfs(1, 0);
			maxn = -1, ff = gg1 = 0;
			dfs1(1, 0, 1, 0, 0);
			int rt = maxid;
			dp[rt] = maxn, dp_f[rt] = ff, dp_g[rt] = gg1;
			rk.push_back(rt);

			dfs(1, 0);
			ff = gg2 = 0;
			dfs1(1, 0, 1, 0, 0);
			dp_ff[rt] = 1 - ff, dp_gg[rt] = gg2;
		}
		// for(int i : rk) cout << i << ' ' << dp_f[i] << ' ' << dp_g[i] << ' ' << dp_ff[i] << ' ' << dp_gg[i] << endl;
	}
}tr[N];

int main()
{
    cin >> n;
    for(int i = 1; i <= n; i++) tr[i].init();

    priority_queue<PDI, vector<PDI>, greater<PDI> > q;
	for(int i = 1; i <= n; i++)
	{
		while(tr[i].rk.back() != tr[i].s) tr[i].rk.pop_back();
		q.push({tr[i].dp[tr[i].s], i});
	}
	while(q.size() == n)
	{
		int t = q.top().second; q.pop();
		double resf = 1, resg = 0;
		for(int i = 1; i <= n; i++)
		{
			double f1 = i == t ? tr[i].dp_f[tr[i].rk.back()] - f[i] : tr[i].dp_ff[tr[i].rk.back()];
			double g1 = i == t ? tr[i].dp_g[tr[i].rk.back()] - g[i] : tr[i].dp_gg[tr[i].rk.back()];
			resg = resg * f1 + resf * g1, resf *= f1;
		}
		ans += resg;

		f[t] = tr[t].dp_f[tr[t].rk.back()], g[t] = tr[t].dp_g[tr[t].rk.back()];
		tr[t].rk.pop_back();
		if(tr[t].rk.empty()) break;
		q.push({tr[t].dp[tr[t].rk.back()], t});
	}
	printf("%.8lf\n", ans);
    cerr << "\ntimes: " << clock() << "ms" << endl;
    return 0;
}

#include <bits/stdc++.h>

using i64 = long long;

void solve() {
	int n;
	std::cin >> n;

	std::string s;
	std::cin >> s;

	std::vector<std::vector<int>> adj(n);
	for (int i = 1; i < n; ++ i) {
		int u, v;
		std::cin >> u >> v;
		u--, v--;
		adj[u].push_back(v);
		adj[v].push_back(u);
	}

	std::vector<std::set<std::array<int, 2>>> S(n);
	std::vector<int> c(n), val(n), ans(n, -1);

	auto dfs = [&](auto &self, int x, int p) -> void {
		if (x) {
			c[x] = c[p];
			val[x] = val[p];
		}
		if (s[x] == '0') {
			c[x]++;
			val[x]--;
		} else {
			c[x]--;
			val[x] += 3;
		}
		S[x].insert({c[x], val[x]});

		auto merge = [&](int y) -> void {
			if (S[x].size() < S[y].size()) {
				std::swap(S[x], S[y]);
			}
			for (auto [curc, curv] : S[y]) {
				auto it = S[x].lower_bound({c[x] + (x == 0 ? 0 : c[p]) - curc, -(1 << 30)});
				if (it != S[x].end()) {
					ans[x] = std::max(ans[x], (*it)[1] + curv - val[x] - (x == 0 ? 0 : val[p]));
				}
			}
			for (auto [curc, curv] : S[y]) {
				auto it = S[x].lower_bound({curc, -(1 << 30)});
				if (it != S[x].end() && (*it)[1] >= curv) {
					continue;
				} else {
					S[x].insert({curc, curv});	
				}
				it = S[x].lower_bound({curc, curv});
				while (it != S[x].begin() && (*prev(it))[1] <= curv) {
					S[x].erase(prev(it));
				}
			}
		};

		for (auto y : adj[x]) {
			if (y == p) {
				continue;
			}
			self(self, y, x);
			merge(y);
			S[y].clear();
		}
	};

	dfs(dfs, 0, -1);
	S[0].clear();
	c[0] = val[0] = 0;
	for (int i = 0; i < n; ++ i) {
		s[i] = '0' + '1' - s[i];
	}
	dfs(dfs, 0, -1);

	for (int i = 0; i < n; ++ i) {
		std::cout << ans[i] << '\n';
	}
}

int main() {
	std::ios::sync_with_stdio(false);
	std::cin.tie(nullptr);

	int T;
	std::cin >> T;

	while (T --) {
		solve();
	}

	return 0;
}

