                A[j+k]=(x+y)%M;
                A[j+i+k]=(x-y)%M;
            }
        }
    }
    if(t==1)return;
    x=ksm(L,M-2);
    for(i=0;i<L;i++)
        A[i]=A[i]*x%M;
