    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(
        A.get(o[i].l)
        -B.get(o[i].l)*2*o[i].l
        +C.get(o[i].l)*o[i].l*o[i].l
      );
    }
  }
  for(;--j>=l;)if(o[j].op==1){
    A.clr(o[j].l);
    A.clr(o[j].r);
    B.clr(o[j].l);
    B.clr(o[j].r);
    C.clr(o[j].l);
    C.clr(o[j].r);
  }
  inplace_merge(o+l,o+1+mid,o+1+r,[&](opts x,opts y){
    return x.r<y.r;
  });
}
void divide2(int l,int r){
  if(l==r)return;
  int mid=(l+r)>>1;
  divide2(l,mid);
  divide2(mid+1,r);
  int j=l;
  for(int i=mid+1;i<=r;i++){
    for(;j<=mid&&o[j].l<o[i].l;j++)if(o[j].op==1){
      C.update(o[j].l,o[j].r,o[j].w);
    }
    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(C.get(o[i].r)*(o[i].r-o[i].l)*(o[i].r-o[i].l));
    }
  }
  for(;--j>=l;)if(o[j].op==1){
    C.clr(o[j].l-1);
    C.clr(o[j].r);
  }
  j=mid;
  for(int i=r;i>mid;i--){
    for(;j>=l&&o[j].l>=o[i].l;j--)if(o[j].op==1){
      A.update(o[j].l,o[j].r,o[j].w*o[j].l*o[j].l);
      B.update(o[j].l,o[j].r,o[j].w*o[j].l);
      C.update(o[j].l,o[j].r,o[j].w);
    }
    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(A.get(o[i].r)-B.get(o[i].r)*2*o[i].r+C.get(o[i].r)*o[i].r*o[i].r);
    }
  }
  for(;++j<=mid;)if(o[j].op==1){
    A.clr(o[j].l-1);
    A.clr(o[j].r);
    B.clr(o[j].l-1);
    B.clr(o[j].r);
    C.clr(o[j].l-1);
    C.clr(o[j].r);
  }
  inplace_merge(o+l,o+1+mid,o+1+r,[&](opts x,opts y){
    return x.l<y.l;
  });
}
