}
BIT U[2],V[2],W[2];
void divide3(int l,int r){
  if(l==r)return;
  int mid=(l+r)>>1;
  divide3(l,mid);
  divide3(mid+1,r);
  int j=l;
  for(int i=mid+1;i<=r;i++){
    for(;j<=mid&&o[j].r<o[i].r;j++)if(o[j].op==1){
      U[o[j].tp].update(0,o[j].r-o[j].l,o[j].w*(o[j].r-o[j].l)*(o[j].r-o[j].l));
      V[o[j].tp].update(0,o[j].r-o[j].l,o[j].w*(o[j].r-o[j].l));
      W[o[j].tp].update(0,o[j].r-o[j].l,o[j].w);
    }
    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(
        U[!o[i].tp].get(o[i].l)
        -V[!o[i].tp].get(o[i].l)*2*o[i].l
        +W[!o[i].tp].get(o[i].l)*o[i].l*o[i].l
      );
    }
  }
  for(;--j>=l;)if(o[j].op==1){
    U[o[j].tp].clr(o[j].r-o[j].l);
    V[o[j].tp].clr(o[j].r-o[j].l);
    W[o[j].tp].clr(o[j].r-o[j].l);
  }
  j=mid;
  for(int i=r;i>mid;i--){
    for(;j>=l&&o[j].r>=o[i].r;j--)if(o[j].op==1){
      U[o[j].tp].add(n-o[j].l,o[j].w*o[j].l*o[j].l);
      V[o[j].tp].add(n-o[j].l,o[j].w*o[j].l);
      W[o[j].tp].add(n-o[j].l,o[j].w);
    }
    if(o[i].op==2){
      ans[o[i].id]+=o[i].w*(
        U[!o[i].tp].get(n-o[i].r+o[i].l)
        -V[!o[i].tp].get(n-o[i].r+o[i].l)*2*(o[i].r-o[i].l)
        +W[!o[i].tp].get(n-o[i].r+o[i].l)*(o[i].r-o[i].l)*(o[i].r-o[i].l)
      );
    }
  }
  for(;++j<=mid;)if(o[j].op==1){
    U[o[j].tp].clr(n-o[j].l);
    V[o[j].tp].clr(n-o[j].l);
    W[o[j].tp].clr(n-o[j].l);
  }
  inplace_merge(o+l,o+1+mid,o+1+r,[&](opts x,opts y){
    return x.r<y.r;
  });
}
