int rd(){int x=0;char ch=getchar();while(!isdigit(ch)) ch=getchar();while(isdigit(ch)) x=(x<<1)+(x<<3)+(ch^48),ch=getchar();return x;}
const int N=22,T=375;
int n,k,cnt[N],L[N][N],P[N][N],p[N];
ll vP[N][N],val[N];
