mt19937_64 rad(time(0));

int ask(int st,string s){
	for(int i=(int)s.size()+1;i<=n;i++) s+='L';
	cout<<"? "<<st<<" "<<s<<"\n";
	cout.flush();
	return rd();
}

pair<int,ll> calc(int st,string s,int i){
	ll v=ask(st,s);
	int x=1;
	for(int y=2;y<=cnt[i+1];y++){
		int a=x,b=y,d=i+1;
		ll w=0;
		string t=s;
		while(1){
			if(L[d][a]!=L[d][b]) a=L[d][a],b=L[d][b],t+='L',d++;
			else{
				t+='P',w+=vP[d][b];
				if(vP[d][a]!=vP[d][b]) break;
				a=P[d][a],b=P[d][b],d++;
			}
		}
		if(ask(st,t)-v==w) x=y;
	}
	return {x,v};
}

