	for(int i=1;i<=n;++i){
		int x,a,b,c,d;
		scanf("%d%d%d%d%d",&x,&a,&b,&c,&d);
		int s=a+b+c+d;
		if(x==1)p1[++t1]=make_pair(s,-i);
