int solve(vector <int> v){
	int l=v.size();
	vector <int> dis=v;
	for(int i=0; i<l; i++)dis[i]=max(dis[i],dis[(i+l-1)%l]-1);
	for(int i=l-1; i>=0; i--)dis[i]=max(dis[i],dis[(i+1)%l]-1);
	for(int i=0; i<l; i++)dis[i]=max(dis[i],dis[(i+l-1)%l]-1);
	for(int i=l-1; i>=0; i--)dis[i]=max(dis[i],dis[(i+1)%l]-1);
	for(int i=0; i<2*l; i++)nex[i]=min(2*l-1,i+l);
	int flg=0;
	for(int i=0; i<l; i++){
		if(dis[i]+v[i]>0)continue;
		flg=1;
		int L=k+v[i];
		if(2*L+1>=l)continue;
		int ll=l+i-L, rr=l+i+L;
		nex[ll-1]=min(nex[ll-1],rr);
		if(ll-l>0)nex[ll-l-1]=min(nex[ll-l-1],rr-l);
	}
	if(!flg)return 0;
	for(int i=2*l-2; i>=0; i--)nex[i]=min(nex[i],nex[i+1]);
	for(int i=0; i<2*l; i++)st[0][i]=nex[i];
	for(int i=1; i<=17; i++)for(int j=0; j<2*l; j++){
		st[i][j]=st[i-1][st[i-1][j]];
