ll qpow(ll a,int b){
	ll s=1;
	while(b){
		if(b&1)s=s*a%P;
		a=a*a%P,b/=2;
	}
	return s;
}
void add(int p,int x,int y){
	(f[p]-=qpow(2,mp[p][x])-1)%=P,(g[p]-=qpow(2,cnt[x]-mp[p][x])-1)%=P;
	mp[p][x]+=y;
	(f[p]+=qpow(2,mp[p][x])-1)%=P,(g[p]+=qpow(2,cnt[x]-mp[p][x])-1)%=P;
}
