	return u.now < v.now;
}
inline bool cmp2(node u, node v){
	return u.now > v.now;
}
inline void solve(node *t, node step){
	for(int i = 1;i < n;i = -~i){
		if(t[i].x == step.x && t[i].y == step.y){
			for(int j = i;j < n;j = -~j) t[j - i + 1] = t[j];
			for(int j = 1;j < i;j = -~j) t[n - i + j] = la[j];
			break;
		}
		la[i] = t[i];
	}
	return ;
}
