inline void send(int b){
	printf("send %d\n",b);fflush(stdout);
}
inline int rcv(){
	printf("receive\n");fflush(stdout);
	int b;scanf("%d",&b);
	return b;
}
int main(){
	scanf("%s",pl+1);
	int he=0;
	for(int i=1;i<=tt;++i){
		R[i]=63-he,L[i]=63-he-fk[i]+1;
		he+=fk[i];
	}
	if(pl[1]=='A'){
		scanf("%llu",&A);
		int fl=0;
		for(int i=1;i<=tt;++i){
			if(fl){
				for(int j=R[i];j>=L[i];--j)send(A>>j&1);
				continue;
			}
			for(int j=R[i];j>=L[i];--j){
				int b=rcv();
				B|=(ull)b<<j;
			}
			if(B>A){
				send(0);fl=1;
				for(int j=R[i];j>=L[i];--j)send(A>>j&1);
			}else send(1);
		}
	}else{
		scanf("%llu",&B);
		int fl=0;
		for(int i=1;i<=tt;++i){
			if(fl){
				for(int j=R[i];j>=L[i];--j)A|=(ull)rcv()<<j;
