				send(B>>j&1);
			}
			if(rcv()){
				for(int j=R[i];j>=L[i];--j)A|=(ull)(B>>j&1)<<j;
				continue;
			}
			fl=1;
			for(int j=R[i];j>=L[i];--j)A|=(ull)rcv()<<j;
		}
	}
	printf("answer %llu\n",min(A,B));fflush(stdout);
