		int mid = (l + r) >> 1;
		put(x << 1, m[x], l, mid);
		put(x << 1 | 1, m[x], mid + 1, r);
		t[x] = 0;
	}
}
void apply(int ql, int qr, func v, int cur = 1, int l = 1, int r = n) {
	if(ql <= l && r <= qr) {
		// off vs a[p] - pos * v
		int min = v.v == 1 ? min0[cur] : min1[cur];
		int max = v.v == 1 ? max0[cur] : max1[cur];
		if(v.off <= min) return put(cur, v, l, r);
		if(v.off >= max) return ;
	}
	int mid = (l + r) >> 1;
	down(cur, l, r);
	if(ql <= mid) apply(ql, qr, v, cur << 1, l, mid);
	if(mid < qr) apply(ql, qr, v, cur << 1 | 1, mid + 1, r);
	update(cur);
}
int query(int ql, int qr, int cur = 1, int l = 1, int r = n) {
	if(ql <= l && r <= qr) {
		return max[cur];
	}
	int mid = (l + r) >> 1, ans = 0;
	down(cur, l, r);
	if(ql <= mid) ans = std::max(ans, query(ql, qr, cur << 1, l, mid));
	if(mid < qr) ans = std::max(ans, query(ql, qr, cur << 1 | 1, mid + 1, r));
	return ans;
}


