struct DS1{
	struct Node{
		ll mn,tag;
	}tr[N<<2];
	inline void PushUp(int x){tr[x].mn=min(tr[x<<1].mn,tr[x<<1|1].mn);}
	inline void Push(int x,ll k){tr[x].mn+=k,tr[x].tag+=k;}
	inline void PushDown(int x){
		if(tr[x].tag){
			Push(x<<1,tr[x].tag);
			Push(x<<1|1,tr[x].tag);
			tr[x].tag=0;
		}
	}

	inline void Build(int x,int L,int R){
		tr[x].tag=0;
		if(L==R) return tr[x].mn=L,void();
		int mid=L+R>>1;
		Build(x<<1,L,mid),Build(x<<1|1,mid+1,R);
		PushUp(x);
	}
	inline void Modify(int x,int L,int R,int l,int r,ll k){
		if(l<=L&&R<=r) return Push(x,k);
		PushDown(x);
		int mid=L+R>>1;
		if(l<=mid) Modify(x<<1,L,mid,l,r,k);
		if(r>mid) Modify(x<<1|1,mid+1,R,l,r,k);
		PushUp(x);
	}
	inline int Find(int x,int L,int R){
		if(L==R) return L+(tr[x].mn>=0);
		PushDown(x);
		int mid=L+R>>1;
		if(tr[x<<1].mn<0) return Find(x<<1,L,mid);
		else return Find(x<<1|1,mid+1,R);
	}
}T;
struct DS2{
	queue<int> q[N];
	int mn[N<<2],p[N];
	inline void PushUp(int x){mn[x]=min(mn[x<<1],mn[x<<1|1]);}
	inline void Build(int x,int L,int R){
		if(L==R) return p[L]=x,mn[x]=INT_MAX,void();
		int mid=L+R>>1;
		Build(x<<1,L,mid),Build(x<<1|1,mid+1,R);
		PushUp(x);
	}
	inline void Update(int i){
		int x=p[i];
		mn[x]=q[i].size()?q[i].front():INT_MAX;
		while(x>>=1) PushUp(x);
	}
	inline int Query(int x,int L,int R,int l,int r){
		if(l<=L&&R<=r) return mn[x];
		int mid=L+R>>1;
		if(r<=mid) return Query(x<<1,L,mid,l,r);
		else if(l>mid) return Query(x<<1|1,mid+1,R,l,r);
		else return min(Query(x<<1,L,mid,l,r),Query(x<<1|1,mid+1,R,l,r));
	}
}Q;
namespace DS3{
