	inline void PushUp(int x){tr[x].sum=tr[tr[x].lc].sum+tr[tr[x].rc].sum;}
	inline void Modify(int &x,int L,int R,int p,ll k){
		x=Clone(x);
		if(L==R) return tr[x].sum+=k,void();
		int mid=L+R>>1;
		if(p<=mid) Modify(tr[x].lc,L,mid,p,k);
		else Modify(tr[x].rc,mid+1,R,p,k);
		PushUp(x);
	}
	inline ll Query(int x,int L,int R,int l,int r){
		if(l>r) return 0;
		if(l<=L&&R<=r) return tr[x].sum;
		int mid=L+R>>1;
		if(r<=mid) return Query(tr[x].lc,L,mid,l,r);
		else if(l>mid) return Query(tr[x].rc,mid+1,R,l,r);
		else return Query(tr[x].lc,L,mid,l,r)+Query(tr[x].rc,mid+1,R,l,r);
	}
	inline int Find(int v1,int p1,int v2,int p2,int L,int R,int l,ll s1,ll s2){
		if(L==R) return L+(s1+tr[v1].sum+tr[p1].sum>=s2+tr[v2].sum+tr[p2].sum);
