		ll ls1=tr[tr[v1].lc].sum+tr[tr[p1].lc].sum;
		ll ls2=tr[tr[v2].lc].sum+tr[tr[p2].lc].sum;
		if(l<=mid&&s1+ls1<s2+ls2) return Find(tr[v1].lc,tr[p1].lc,tr[v2].lc,tr[p2].lc,L,mid,l,s1,s2);
		else return Find(tr[v1].rc,tr[p1].rc,tr[v2].rc,tr[p2].rc,mid+1,R,l,s1+ls1,s2+ls2);
