			ll s2=-l2-DS3::Query(Vrt[l2-1],1,n,1,i)-DS3::Query(Prt[d2][p2],1,n,1,i);
			
			return DS3::Find(Vrt[l1-1],Prt[d1][p1],Vrt[l2-1],Prt[d2][p2],1,n,i+1,s1,s2);
		};
		vector<int> p={0},t={i};
		for(int j=1;j<itv[i].size();j++){
			while(true){
				int k=Tick(p.back(),j);
				if(k<t.back()){
					p.pop_back();
					t.pop_back();
				}else{
					t.push_back(k);
					break ;
				}
			}
			p.push_back(j);
		}
		for(int j=0;j<p.size();j++){
			ins[t[j]].push_back({i,p[j]});
			if(j+1<p.size()) ers[t[j+1]].push_back({i,p[j]});
		}
	}

	vector<ll> res;
	for(int k=1;k<=n;k++){
		InsP(1,1,n,0,k);
		ans+=Ta.Ask(a[k],n);
		ans+=a[k];
		for(auto p:ers[k]){
			int i=p[0],j=p[1];
			InsI(itv[i][j][0],itv[i][j][1],itv[i][j][2],itv[i][j][3],i,-1);
			ans-=DS3::Query(Vrt[itv[i][j][1]-1],1,n,i+1,k);
		}
		for(auto p:ins[k]){
			int i=p[0],j=p[1];
			InsI(itv[i][j][0],itv[i][j][1],itv[i][j][2],itv[i][j][3],i,1);
			ans+=DS3::Query(Vrt[itv[i][j][1]-1],1,n,i+1,k);
		}
		Ta.Add(a[k],-1);
		res.push_back(ans);
	}

	for(ll x:res) cout<<x<<' ';cout<<endl;

	return 0;
}

