#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int G = 3;
using ll = long long;

int Q;

ll qpow(ll a, ll e) {
    ll r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

void ntt(vector<int>& a, bool inv) {
    int n = a.size();

    for (int i = 1, j = 0; i < n; i++) {
        int bit = n >> 1;
        for (; j & bit; bit >>= 1) j ^= bit;
        j ^= bit;
        if (i < j) swap(a[i], a[j]);
    }

    for (int len = 2; len <= n; len <<= 1) {
        int wlen = qpow(G, (MOD - 1) / len);
        if (inv) wlen = qpow(wlen, MOD - 2);

        for (int i = 0; i < n; i += len) {
            ll w = 1;
            int half = len >> 1;

            for (int j = 0; j < half; j++) {
                int u = a[i + j];
                int v = w * a[i + j + half] % MOD;

                int x = u + v;
                if (x >= MOD) x -= MOD;

                int y = u - v;
                if (y < 0) y += MOD;

                a[i + j] = x;
                a[i + j + half] = y;

                w = w * wlen % MOD;
            }
        }
    }

    if (inv) {
        int invn = qpow(n, MOD - 2);
        for (int& x : a) {
            x = 1LL * x * invn % MOD;
        }
    }
}

vector<int> multiply(vector<int> a, vector<int> b, int limit) {
    if (limit <= 0 || a.empty() || b.empty()) return {};

    if ((int)a.size() > limit) a.resize(limit);
    if ((int)b.size() > limit) b.resize(limit);

    int need = min(limit, (int)a.size() + (int)b.size() - 1);
    if (need <= 0) return {};

    if (1LL * a.size() * b.size() <= 40000) {
        vector<int> c(need);

        for (int i = 0; i < (int)a.size(); i++) {
            if (!a[i]) continue;

            for (int j = 0; j < (int)b.size() && i + j < need; j++) {
                if (!b[j]) continue;
                c[i + j] = (c[i + j] + 1LL * a[i] * b[j]) % MOD;
            }
        }

        return c;
    }

    int n = 1;
    while (n < (int)a.size() + (int)b.size() - 1) n <<= 1;

    a.resize(n);
    b.resize(n);

    ntt(a, false);
    ntt(b, false);

    for (int i = 0; i < n; i++) {
        a[i] = 1LL * a[i] * b[i] % MOD;
    }

    ntt(a, true);
    a.resize(need);

    return a;
}

vector<int> wcoef, bcoef, val, pw;

void addConv(const vector<int>& A, const vector<int>& B, int l, int mid, int r) {
    if (A.empty() || B.empty()) return;

    auto C = multiply(A, B, r - l);

    for (int p = 0; p < (int)C.size(); p++) {
        int t = l + p + 1;

        if (t >= mid + 1 && t <= r) {
            val[t] += 1LL * Q * C[p] % MOD;
            if (val[t] >= MOD) val[t] -= MOD;
        }
    }
}

void update_cdq(int l, int mid, int r) {
    int maxOther = r - l - 1;
    if (maxOther < 0) return;

    int bEnd = min(mid, maxOther);

    if (bEnd >= 0) {
        vector<int> A(wcoef.begin() + l, wcoef.begin() + mid + 1);
        vector<int> B(bcoef.begin(), bcoef.begin() + bEnd + 1);
        addConv(A, B, l, mid, r);
    }

    int aEnd = min(l - 1, maxOther);

    if (aEnd >= 0) {
        vector<int> A(wcoef.begin(), wcoef.begin() + aEnd + 1);
        vector<int> B(bcoef.begin() + l, bcoef.begin() + mid + 1);
        addConv(A, B, l, mid, r);
    }
}

void cdq(int l, int r) {
    if (l == r) {
        if (l == 0) {
            wcoef[l] = 1;
        } else {
            wcoef[l] = val[l];
        }

        bcoef[l] = 1LL * pw[l] * wcoef[l] % MOD;
        return;
    }

    int mid = (l + r) >> 1;

    cdq(l, mid);
    update_cdq(l, mid, r);
    cdq(mid + 1, r);
}

vector<int> polyPow(vector<int> base, long long exp, int limit) {
    vector<int> res(1, 1);

    if ((int)base.size() > limit) base.resize(limit);

    while (exp) {
        if (exp & 1) {
            res = multiply(res, base, limit);
        }

        exp >>= 1;

        if (exp) {
            base = multiply(base, base, limit);
        }
    }

    res.resize(limit);
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n >> Q;

    int N = n + 1; 
    int K = n;     

    wcoef.assign(K + 1, 0);
    bcoef.assign(K + 1, 0);
    val.assign(K + 1, 0);
    pw.assign(K + 1, 1);

    for (int i = 1; i <= K; i++) {
        pw[i] = 1LL * pw[i - 1] * Q % MOD;
    }

    cdq(0, K);

    vector<int> phi(N + 1, 0);

    phi[0] = 1;

    for (int i = 1; i <= N; i++) {
        phi[i] = wcoef[i - 1];
    }

    auto p = polyPow(phi, N + 1, N + 1);

    int non_single = 1LL * p[N] * qpow(N + 1, MOD - 2) % MOD;

    int ans = 1LL * non_single * qpow(Q, N) % MOD;

    cout << ans << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

double f[2][3][3][7][7][150][150];
int act[2][3][3][7][7][150][150];
int tag[2][3][3][7][7][150][150];

struct player
{
	int hp,u[2];

	void work() { u[0] < u[1] && (swap(u[0],u[1]), 1); }

	player () : hp(5), u{ 0,0 } {}

	player (int h,int d,int m,int c,int k) : hp(h)
	{
		u[0] = u[1] = 0; int t = 0;
		
		if(k) u[t++] = 4, --k;
		if(k) u[t++] = 4, --k;
		if(c) u[t++] = 3, --c;
		if(c) u[t++] = 3, --c;
		if(m) u[t++] = 2, --m;
		if(m) u[t++] = 2, --m;
		if(d) u[t++] = 1, --d;
		if(d) u[t++] = 1, --d;
	}

	bool use(int x)
	{
		if(u[1] == x) return u[1] = 0, work(), true;
		if(u[0] == x) return u[0] = 0, work(), true;
		return false;
	}

	int id() { return hp * 25 + u[0] * 5 + u[1]; }
};

struct state
{
	int ph,cur,cg,l,b; player p1,p2;

	state () : ph(1) { cur = cg = l = b = 0; }

	void shoot(int u)
	{
		assert(!ph && u && (!cur || u == cur));
		
		cur = 0;
		if(u == 1) assert(l--);
		else assert(b--);
	}

	bool turn()
	{
		assert(!ph);
		if(cg == 1) return cg = 2, false;
		else return cg = 0, swap(p1,p2), true;
	}

	void get(double *&u,int *&v,int *&w)
	{
		u = &f[ph][cur][cg][l][b][p1.id()][p2.id()],
		v = &act[ph][cur][cg][l][b][p1.id()][p2.id()],
		w = &tag[ph][cur][cg][l][b][p1.id()][p2.id()];
	}

	void output()
	{
		fprintf(stderr,"ph=%d, cr=%d, cg=%d, (l,b)=(%d,%d), ",ph,cur,cg,l,b),
		fprintf(stderr,"(%d,%d,%d), (%d,%d,%d)\n",p1.hp,p1.u[0],p1.u[1],p2.hp,p2.u[0],p2.u[1]);
	}
};

const int N = 2.1e6; int l = 1, r = 0;

struct trans{ double *val,pro; bool opt; };

struct node
{
	state s;
	vector < vector < trans > > vec;
} q[N];

void insert(state s)
{
	double *u; int *v,*w; s.get(u,v,w);

	if(!*w) *w = 1, q[++r].s = s;
}

void work(node *x)
{
	x -> vec.clear();

	state s = x -> s, nxt;
	double *u; int *v,*w;
	vector < trans > tmp;

	// s.output();

	assert(s.l >= 0 && s.b >= 0 && s.l + s.b <= 6);

	if(!s.p1.hp || !s.p2.hp) return;

	if(s.ph == 1) // restarting
	{
		tmp.clear(), assert(!s.cur);

		if(s.l + s.b < 6)
		{
			nxt = s, ++nxt.l, nxt.get(u,v,w),
			tmp.push_back((trans){ u,0.5,0 }), insert(nxt);

			nxt = s, ++nxt.b, nxt.get(u,v,w);
			tmp.push_back((trans){ u,0.5,0 }), insert(nxt);
		}
		else if(s.p1.u[0] && s.p1.u[1] && s.p2.u[0] && s.p2.u[1]) // restarting completed
			nxt = s, nxt.ph = 0, nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0,0 }), insert(nxt);
		else
		{
			int *tp;
			
			nxt = s;
			if(!s.p1.u[0]) tp = &nxt.p1.u[0];
			else if(!s.p1.u[1]) tp = &nxt.p1.u[1];
			else if(!s.p2.u[0]) tp = &nxt.p2.u[0];
			else if(!s.p2.u[1]) tp = &nxt.p2.u[1];

			for(int i = 1;i <= 4; ++ i)
				*tp = i, nxt.get(u,v,w),
				tmp.push_back((trans){ u,0.25,0 }), insert(nxt);
			
			assert(tmp.size() == 4);
		}

		x -> vec.push_back(tmp);
		return;
	}

	if(!s.l && !s.b) // begin restarting
	{
		nxt = s, nxt.ph = 1, nxt.cur = 0, nxt.get(u,v,w),
		tmp.push_back((trans){ u,1.0,0 }), insert(nxt),
		x -> vec.push_back(tmp);

		return;
	}

	// gaming!!!

	int cur = s.cur; bool op;

	// 1. Fire at opponent
	tmp.clear();
	if(cur == 0 && s.l && s.b)
		nxt = s, nxt.shoot(1), --nxt.p2.hp, op = nxt.turn(), nxt.get(u,v,w),
		tmp.push_back((trans){ u,1.0 * s.l / (s.l + s.b),op }), insert(nxt),

		nxt = s, nxt.shoot(2), op = nxt.turn(), nxt.get(u,v,w),
		tmp.push_back((trans){ u,1.0 * s.b / (s.l + s.b),op }), insert(nxt);
	else
		nxt = s, (cur == 1 || !s.b) && (--nxt.p2.hp),
		nxt.shoot(cur ? cur : s.l ? 1 : 2), op = nxt.turn(), nxt.get(u,v,w),
		tmp.push_back((trans){ u,1.0,op }), insert(nxt);
	
	x -> vec.push_back(tmp);

	// 2. Fire at self
	tmp.clear();
	if(cur == 0 && s.l && s.b)
		nxt = s, nxt.shoot(1), --nxt.p1.hp, op = nxt.turn(), nxt.get(u,v,w),
		tmp.push_back((trans){ u,1.0 * s.l / (s.l + s.b),op }), insert(nxt),

		nxt = s, nxt.shoot(2), op = 0, nxt.get(u,v,w),
		tmp.push_back((trans){ u,1.0 * s.b / (s.l + s.b),op }), insert(nxt);
	else
		nxt = s, op = 0, (cur == 1 || !s.b) && (--nxt.p1.hp, op = nxt.turn()),
		nxt.shoot(cur ? cur : s.l ? 1 : 2), nxt.get(u,v,w),
		tmp.push_back((trans){ u,1.0,op }), insert(nxt);
	x -> vec.push_back(tmp);

	// 3. Dummy
	tmp.clear(); player p1 = s.p1;
	if(p1.use(1))
	{
		if(cur == 0 && s.l && s.b)
			nxt = s, nxt.p1 = p1, nxt.shoot(1), nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0 * s.l / (s.l + s.b),0 }), insert(nxt),

			nxt = s, nxt.p1 = p1, nxt.shoot(2), nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0 * s.b / (s.l + s.b),0 }), insert(nxt);
		else
			nxt = s, nxt.p1 = p1, nxt.shoot(cur ? cur : s.l ? 1 : 2), nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0,0 }), insert(nxt);
	}
	x -> vec.push_back(tmp);

	// 4. Magnifier
	tmp.clear(), p1 = s.p1;
	if(p1.use(2))
	{
		if(cur == 0 && s.l && s.b)
			nxt = s, nxt.p1 = p1, nxt.cur = 1, nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0 * s.l / (s.l + s.b),0 }), insert(nxt),

			nxt = s, nxt.p1 = p1, nxt.cur = 2, nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0 * s.b / (s.l + s.b),0 }), insert(nxt);
		else
			nxt = s, nxt.p1 = p1, nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0,0 }), insert(nxt);
	}
	x -> vec.push_back(tmp);

	// 5. Converter
	tmp.clear(), p1 = s.p1;
	if(p1.use(3))
	{
		if(cur == 0 && s.l && s.b)
			nxt = s, nxt.p1 = p1, --nxt.l, ++nxt.b, nxt.cur = 2, nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0 * s.l / (s.l + s.b),0 }), insert(nxt),

			nxt = s, nxt.p1 = p1, ++nxt.l, --nxt.b, nxt.cur = 1, nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0 * s.b / (s.l + s.b),0 }), insert(nxt);
		else if(cur == 1 || !s.b) // must be LIVE -> BLANK
			nxt = s, nxt.p1 = p1, --nxt.l, ++nxt.b, nxt.cur = 2, nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0,0 }), insert(nxt);
		else // must be BLANK -> LIVE
			nxt = s, nxt.p1 = p1, ++nxt.l, --nxt.b, nxt.cur = 1, nxt.get(u,v,w),
			tmp.push_back((trans){ u,1.0,0 }), insert(nxt);
	}
	x -> vec.push_back(tmp);

	// 6. Cage
	tmp.clear(), p1 = s.p1;
	if(p1.use(4) && s.cg == 0)
	{
		nxt = s, nxt.p1 = p1, nxt.cg = 1, nxt.get(u,v,w),
		tmp.push_back((trans){ u,1.0,0 }), insert(nxt);
	}
	x -> vec.push_back(tmp);
}

void update(node *x)
{
	state s = x -> s;
	double *u, val; int *v,*w;

	s.get(u,v,w);

	if(!s.p1.hp) { *u = 0.0; return; }
	if(!s.p2.hp) { *u = 1.0; return; }

	*u = -1e7, *v = 0; int i = 0;

	for(auto &vec : x -> vec)
	{
		++ i;
		if(!vec.size()) continue;

		val = 0.0;
		for(auto [v, pro, opt] : vec)
			if(opt) val += pro * (1.0 - *v);
			else val += pro * (*v);
		
		if(val > *u) *u = val, *v = i;
	}
}

void input(state *s)
{
	s -> ph = 0, scanf("%d%d",&s -> l,&s -> b);

	int h,d,m,c,k;
	
