using namespace std;
char s[300005];
const int B=26;
struct apple{
	int c[B];
	long long nx,zh,b[B];
}sm[1200005],a0;
apple operator+(const apple& a,const apple& b){
	apple c;
	c.nx=a.nx+b.nx,c.zh=a.zh+b.zh;
	int h=0;
	for(int i=B-1;i>=0;--i){
		c.nx+=1ll*h*b.c[i];
		c.c[i]=a.c[i]+b.c[i];
		c.zh+=-1ll*b.c[i]*h*h+b.b[i]*h;
		c.b[i]=a.b[i]+b.b[i]-2ll*b.c[i]*h;
		h+=a.c[i];
	}
	return c;
}
int lz[1200005];
void build(int l,int r,int o){
	lz[o]=0;
	if(l==r){
		sm[o]=a0;
		int u=s[l]-'A';
		sm[o].c[u]=1,sm[o].b[u]=2*l-1;
		return;
	}
	int mid=(l+r)>>1;
	build(l,mid,o<<1);build(mid+1,r,o<<1|1);
	sm[o]=sm[o<<1]+sm[o<<1|1];
}
int LL[26],RR[26];
inline void put(int o,int l,int r){
	sm[o].nx=sm[o].zh=0;
	for(int i=0;i<26;++i){
		int L=max(l,LL[i]),R=min(r,RR[i]);
		if(L>R){
			sm[o].c[i]=sm[o].b[i]=0;continue;
		}
		sm[o].c[i]=R-L+1;
		sm[o].b[i]=1ll*(R-L+1)*(R+L-1);
	}
	lz[o]=1;
}
inline void pushdown(int o,int l,int r){
	if(lz[o]){
		int mid=(l+r)>>1,t=l-1;
		for(int i=0;i<26;++i){
			int z=sm[o].c[i];
			LL[i]=t+1,RR[i]=t+z;t+=z;
		}
		put(o<<1,l,mid),put(o<<1|1,mid+1,r);
		lz[o]=0;
	}
}
void add(int l,int r,int o,int x,int u){
	if(l==r){
		sm[o]=a0;
		sm[o].c[u]=1,sm[o].b[u]=2*l-1;
		return;
	}
	pushdown(o,l,r);
	int mid=(l+r)>>1;
	if(x<=mid)add(l,mid,o<<1,x,u);
	else add(mid+1,r,o<<1|1,x,u);
	sm[o]=sm[o<<1]+sm[o<<1|1];
}
apple xx;
void query(int l,int r,int o,int ll,int rr){
	if(l>=ll&&r<=rr){
		xx=xx+sm[o];return;
	}
	pushdown(o,l,r);
	int mid=(l+r)>>1;
	if(mid>=ll)query(l,mid,o<<1,ll,rr);
	if(mid<rr)query(mid+1,r,o<<1|1,ll,rr);
}
void gai(int l,int r,int o,int ll,int rr){
	if(l>=ll&&r<=rr){
		put(o,l,r);return;
	}
	pushdown(o,l,r);
	int mid=(l+r)>>1;
	if(mid>=ll)gai(l,mid,o<<1,ll,rr);
	if(mid<rr)gai(mid+1,r,o<<1|1,ll,rr);
	sm[o]=sm[o<<1]+sm[o<<1|1];
}
