vector<Int> create(int T) {
  const int N = (T-1) + (1 << (T-1));
  vector<Int> P(1 << N, 0);
  for (int h = 0; h < 1 << N; ++h) {
    const int u = h & ((1 << (T-1)) - 1);
    P[h] = (h >> (T-1+u) & 1) * 2;
  }
  return P;
}

void exper() {
  for (int T = 1; T <= 5; ++T) {
    const auto P = create(T);
    const int N = (T-1) + (1 << (T-1));
    Int total = 0;
    for (int h = 0; h < 1 << N; ++h) total += P[h];
//cerr<<"T = "<<T<<", N = "<<N<<": P = "<<P<<endl;
    assert(total == (1LL << N));
    for (int I = 0; I < 1 << N; ++I) if (__builtin_popcount(I) == T) {
      const int J = (1 << N) - 1 - I;
      Int posi = 0, nega = 0;
      for (int q = I; ; --q &= I) {
        Int sum = 0;
        for (int r = J; ; --r &= J) {
          sum += P[q | r];
          if (!r) break;
        }
        // sum/total - 2^-T
        const Int diff = sum - (1LL << (N - T));
        posi += max(+diff, 0LL);
        nega += max(-diff, 0LL);
        if (!q) break;
      }
      const Int lim = (Int)T << (N-T);
      assert(posi <= lim);
      assert(nega <= lim);
    }
  }
}

