int ksm(int a,int b){
	int res=1;
	while(b){
		if(b&1) res=res*a%mod;
		a=a*a%mod;
		b>>=1;
	}
	return res;
}
int C(int n,int m){
	if(n<0||n<m) return 0;
	return fac[n]*ifac[m]%mod*ifac[n-m]%mod;
}
void ntt(int *A,int lim,bool op){
	for(int i=1;i<lim;i++) if(i<r[i]) swap(A[i],A[r[i]]);
	for(int mid=1;mid<lim;mid<<=1){
		int wn=ksm(op?iG:3,(mod-1)/(mid<<1)); 
		for(int i=0;i<lim;i+=(mid<<1)){
			int w=1;
			for(int j=0;j<mid;j++,w=w*wn%mod){
				int u=A[i+j],v=w*A[i+j+mid]%mod;
				A[i+j]=(u+v)%mod;
				A[i+j+mid]=(u-v+mod)%mod;
			}
		}
	}
	if(op){
		int I=ksm(lim,mod-2);
		for(int i=0;i<lim;i++)A[i]=A[i]*I%mod;
	}
}
void trans(int *f,int v){
