	for(int i=0;i<m;i++)c[i]=a[i]*b[i]%mod;
	ntt(c,m,1);
	int res=1;
	for(int i=0;i<=n;i++){
		f[i]=ifac[i]*res%mod*c[n+i]%mod;
		res=res*v%mod;
	}
}
