int n,m,a,b,A[20005];
struct edge{
	int nxt,to,w;
}e[1000005];
int head[20005],cur[20005],d[20005],tot;
void adde(int u,int v,int w){
	e[++tot]={head[u],v,w};head[u]=tot;
	e[++tot]={head[v],u,0};head[v]=tot;
}
queue<int>q;
bool bfs(int s,int t){
	for(int i=0;i<=m*2+2;i++)d[i]=-1,cur[i]=head[i];
	q.push(s);d[s]=0;
	while(q.size()){
		int u=q.front();q.pop();
		for(int i=head[u];~i;i=e[i].nxt){
			int v=e[i].to;
			if(e[i].w&&d[v]==-1){
				d[v]=d[u]+1;
				q.push(v);
			}
		}
	}
	return d[t]>=0;
}
int dfs(int u,int t,int fl){
	if(u==t||!fl)return fl;
	int res=0;
	for(int &i=cur[u];~i;i=e[i].nxt){
		int v=e[i].to,w=e[i].w;
		if(d[v]!=d[u]+1)continue;
		int k=dfs(v,t,min(w,fl));
		e[i].w-=k;e[i^1].w+=k;
		res+=k;fl-=k;
		if(!fl)break;
	}
	return res;
}
int Dinic(int s,int t){
	int res=0;
	while(bfs(s,t))res+=dfs(s,t,1e9);
	return res;
}
