		for(int i=1;i<=n3;i++)ans[i]=ans2[i];
	}
}

void calc1(vector<int> s){
	for(int i=1;i<=n3+1;i++)cnt2[i]=cnt1[i];
	for(int x:s)if(--cnt2[x]<0)return;
	int pos=getpos(s);
	int cnt=0;
	for(int i=1;i<=n3+1;i++){
		if(i==pos)for(int x:s)ans2[++cnt]=x;
		while(cnt2[i]--)ans2[++cnt]=i;
	}
	update();
}

void calc2(vector<int> s1,vector<int> s2){
	for(int i=1;i<=n3+1;i++)cnt2[i]=cnt1[i];
	for(int x:s1)if(--cnt2[x]<0)return;
	for(int x:s2)if(--cnt2[x]<0)return;
