struct Data {
  INT dx, dy;
  INT sum[2][3];
  Data() : dx(0), dy(0), sum{} {}
  friend Data operator*(const Data &a, const Data &b) {
    Data c;
    c.dx = a.dx + b.dx;
    c.dy = a.dy + b.dy;
    INT tmp[2][3];
    memcpy(tmp, b.sum, sizeof(b.sum));
    for (int l = 0; l <= 2; ++l) {
      tmp[1][l] += tmp[0][l] * a.dx;
    }
    for (int k = 0; k <= 1; ++k) {
      tmp[k][2] += (tmp[k][0] * a.dy + 2 * tmp[k][1]) * a.dy;
      tmp[k][1] += tmp[k][0] * a.dy;
    }
    for (int k = 0; k <= 1; ++k) for (int l = 0; l <= 2; ++l) {
      c.sum[k][l] = a.sum[k][l] + tmp[k][l];
    }
    return c;
  }
  Data pow(INT e) const {
    Data a = *this, b;
    for (; ; a = a * a) {
      if (e & 1) b = b * a;
      if (!(e >>= 1)) return b;
    }
  }
};


// floor((an+b)/m) = X[n]
INT N, K;
vector<INT> X;

/*
  count (m, a, b) s.t. 1 <= m <= M
  
  X[n] <= (an+b)/m < X[n]+1
  X[n] - (a/m)n <= b/m < X[n]+1 - (a/m)n
  max[n] (X[n] - (a/m)n) <= b/m < min[n] (X[n]+1 - (a/m)n)
  convex <= b/m < concave
  
  piecewise
    l < a/m <= r
    X[n0] - (a/m)n0 <= b/m < X[n1]+1 - (a/m)n1
    
    where  X[n0] - c n0 <= X[n1]+1 - c n1  on  l <= c <= r
    
    \sum[1<=m<=M] \sum[lm<a<=rm] ((X[n1]+1 - X[n0]) m + (n0 - n1) a)
    = \sum[0<=m<=M] \sum[floor(lm)<a<=floor(rm)] ((X[n1]+1 - X[n0]) m + (n0 - n1) a)
*/
vector<pair<pair<RAT, RAT>, pair<INT, INT>>> pieces;
INT calc(INT M) {
  auto getSums = [&](RAT c) -> Data {
    Data x, y;
    x.dx = 1;
    x.sum[0][0] = 1;
    y.dy = 1;
    if (c.p < 0) {
      auto res = pathUnder<INT>(c.q, -c.p, c.q - 1, M + 1, Data(), x, y);
      for (int k = 0; k <= 1; ++k) res.sum[k][1] *= -1;
      return res;
    } else {
      return pathUnder<INT>(c.q, c.p, 0, M + 1, Data(), x, y);
    }
  };
  INT ret = 0;
  for (const auto &piece : pieces) {
    const RAT l = piece.first.first;
    const RAT r = piece.first.second;
    const INT n0 = piece.second.first;
    const INT n1 = piece.second.second;
    const auto resL = getSums(l);
    const auto resR = getSums(r);
// cerr<<piece<<" "<<(resR.sum[1][1] - resL.sum[1][1])<<" "<<((resR.sum[0][2] + resR.sum[0][1]) / 2 - (resL.sum[0][2] + resL.sum[0][1]) / 2)<<endl;
    ret += ((X[n1]+1) - X[n0]) * (resR.sum[1][1] - resL.sum[1][1]);
    ret += (n0 - n1) * ((resR.sum[0][2] + resR.sum[0][1]) / 2 - (resL.sum[0][2] + resL.sum[0][1]) / 2);
  }
// cerr<<"calc "<<M<<" = "<<ret<<endl;
  return ret;
}

int main() {
  for (int numCases; ~scanf("%d", &numCases); ) { for (int caseId = 1; caseId <= numCases; ++caseId) {
    N = inInt128();
    K = inInt128();
    X.resize(N);
    for (INT n = 0; n < N; ++n) X[n] = inInt128();
    
    vector<INT> ns0, ns1;
    vector<RAT> cs0, cs1;
    // lower bound: convex
    ns0.push_back(N - 1);
    for (INT n = N - 1; --n >= 0; ) {
      for (; ; ) {
        const RAT c(X[ns0.back()] - X[n], ns0.back() - n);
        if (!cs0.size() || cs0.back() < c) {
          ns0.push_back(n);
          cs0.push_back(c);
          break;
        }
        ns0.pop_back();
        cs0.pop_back();
      }
    }
    // upper bound: concave
    ns1.push_back(0);
    for (INT n = 1; n < N; ++n) {
      for (; ; ) {
        const RAT c(X[n] - X[ns1.back()], n - ns1.back());
        if (!cs1.size() || cs1.back() < c) {
          ns1.push_back(n);
          cs1.push_back(c);
          break;
        }
        ns1.pop_back();
        cs1.pop_back();
      }
    }
// cerr<<"ns0 = "<<ns0<<", cs0 = "<<cs0<<endl;
// cerr<<"ns1 = "<<ns1<<", cs1 = "<<cs1<<endl;
    const int len0 = cs0.size();
    const int len1 = cs1.size();
    
    pieces.clear();
    for (int i = 0, j = 0; ; ) {
      RAT l, r;
      if (i == 0) {
        if (j == 0) {
          // X[N-1] - c (N-1) <= X[0]+1 - c 0
          l = RAT(X[N-1] - (X[0]+1), N-1);
        } else {
          l = cs1[j - 1];
        }
      } else {
        if (j == 0) {
          l = cs0[i - 1];
        } else {
          l = max(cs0[i - 1], cs1[j - 1]);
        }
      }
      if (i == len0) {
        if (j == len1) {
          // X[0] - c 0 <= X[N-1]+1 - c (N-1)
          r = RAT((X[N-1]+1) - X[0], N-1);
        } else {
          r = cs1[j];
        }
      } else {
        if (j == len1) {
          r = cs0[i];
        } else {
          r = min(cs0[i], cs1[j]);
        }
      }
      int ii = i, jj = j;
      if (i < len0 && cs0[i] == r) ++ii;
      if (j < len1 && cs1[j] == r) ++jj;
      const INT n0 = ns0[i], n1 = ns1[j];
      // X[n0] - c n0 <= X[n1]+1 - c n1
      if (n0 < n1) chmin(r, RAT((X[n1]+1) - X[n0], n1 - n0));
      if (n0 > n1) chmax(l, RAT(X[n0] - (X[n1]+1), n0 - n1));
      if (l < r && !(n0 == n1 && X[n0] > X[n1]+1)) {
// cerr<<i<<" "<<j<<" ["<<l<<", "<<r<<"]"<<" "<<n0<<" "<<n1<<endl;
        pieces.emplace_back(make_pair(l, r), make_pair(n0, n1));
      }
      if (i == len0 && j == len1) break;
      i = ii;
      j = jj;
    }
    
// for(INT m=0;m<=4;++m)calc(m);
    constexpr INT MAX_M = (1LL << 30) - 1;
    INT lo = 0, hi = 1;
    for (; hi < MAX_M && calc(hi) < K; ) {
      lo = hi;
      (hi *= 2) += 1;
    }
    if (calc(hi) >= K) {
      for (; lo + 1 < hi; ) {
        const INT mid = (lo + hi) / 2;
        ((calc(mid) >= K) ? hi : lo) = mid;
      }
      const INT M = hi;
      K -= calc(lo);
      INT A = 0, B = 0;
      for (const auto &piece : pieces) {
        const RAT l = piece.first.first;
        const RAT r = piece.first.second;
        const INT n0 = piece.second.first;
        const INT n1 = piece.second.second;
        const INT al = divFloor(l.p * M, l.q);
        const INT ar = divFloor(r.p * M, r.q);
        // (al, a]
        auto sub = [&](INT a) -> INT {
          INT ret = 0;
          ret += ((X[n1]+1) - X[n0]) * M * (a - al);
          ret += (n0 - n1) * (a*(a+1)/2 - al*(al+1)/2);
          return ret;
        };
        const INT tot = sub(ar);
// cerr<<piece<<" ("<<al<<", "<<ar<<"] "<<tot<<endl;
        if (tot >= K) {
          INT alo = al, ahi = ar;
          for (; alo + 1 < ahi; ) {
            const INT mid = (alo + ahi) / 2;
            ((sub(mid) >= K) ? ahi : alo) = mid;
          }
          A = ahi;
          K -= sub(alo);
          const INT b0 = X[n0] * M - n0 * A;
          const INT b1 = (X[n1]+1) * M - n1 * A;
          assert(b0 <= b1);
          assert(b1 - b0 >= K);
          B = b0 + (K-1);
          break;
        } else {
          K -= tot;
        }
      }
      out(M);
      printf(" "); out(A);
      printf(" "); out(B);
      puts("");
    } else {
      puts("-1");
    }
  }
#ifndef LOCAL
  break;
#endif
  }
  return 0;
