void ATRI()
{
	ll n,m;int a,b,r;cin>>n>>m>>a>>b>>r;a*=b;
	if(n>m)swap(n,m);
	ll ans=0,t=(n-1)/(r-1);ans+=t*(r-1)*(r-1),n-=t*(r-1),m-=t*(r-1);
	auto get=[=](int n){ll res=0;for(int i=1;i<=n;++i)res=res*r+1;return res;};
	auto calc=[=](int n,int m,int a){lll x=(lll)a*get(n)*get(m),res=0;while(x)res+=x%r,x/=r;return res;};
	if(m<=r)ans+=calc(n,m,a);
	else ans+=calc(n,r,a),ans+=(m-r)*((a*n-1)%(r-1)+1);
	string s;
	while(ans)s+=ans%r+'0',ans/=r;
	reverse(s.begin(),s.end());
	cout<<s<<"\n";
}
