const int N=1e6+5;
const int mod=998244353;
int qpow(int x,int y=mod-2){
	int res=1;
	while(y){
		if(y&1)	res=res*x%mod;
		x=x*x%mod;
		y>>=1;
	}
	return res;
}
int l,n;
int fac[N],inv[N];
int C(int x,int y){
	if(x<y)	return 0;
	if(x<0||y<0)	return 0;
	return fac[x]*inv[y]%mod*inv[x-y]%mod;
}
