	for(int i=l;i>=1;i--)
		inv[i-1]=inv[i]*i%mod;
	for(int i=1;i<=l;i++){
		for(int j=0,t=1;i*j<=l;j++,t*=-1){
			ans[i]=(ans[i]+(t+mod)*C(n,j)%mod*C(l-i*j-1,n-1)%mod)%mod;
