#include<bits/stdc++.h>
#define N 500050
#define ls (rt<<1)
#define rs (rt<<1|1)
#define ll long long
#define pii pair<ll,ll>
#define fi first
#define se second
#define mp make_pair
#define lim 1000000000ll
using namespace std;
ll a[N];
pii tr[(N>>3)+9];
inline pii merge(pii x,pii y){
	if(y.se==x.fi)return mp(y.fi,x.se);
	else if(y.se>x.fi)return mp(y.fi,lim);
	else if(y.se<x.fi)return mp(y.fi,-lim);
}
void upd(int rt,int l,int r,int x,pii v){
	if(l==r)tr[rt]=v;
	else{
		int mid=l+r>>1;
		if(x<=mid)upd(ls,l,mid,x,v);
		else upd(rs,mid+1,r,x,v);
		tr[rt]=merge(tr[ls],tr[rs]);
	}
}
pii qry(int rt,int l,int r,int ql,int qr){
	if(ql<=l&&qr>=r)return tr[rt];
	else{
		int mid=l+r>>1;
		if(ql<=mid&&qr>mid)return merge(qry(ls,l,mid,ql,qr),qry(rs,mid+1,r,ql,qr));
		else if(qr<=mid)return qry(ls,l,mid,ql,qr);
		else return qry(rs,mid+1,r,ql,qr);
	}
}
int n,q;
inline pii calc(int l,int r){
	ll b=0;
	for(int i=r;i>=l;i--)b=b*2+a[i];
	ll c=(lim-b)>>32;
	ll d=min(max((c<<32)+b,-lim),lim);
	return mp(c,d);
}
void solve(){
	cin>>n>>q;for(int i=0;i<n;i++)cin>>a[i];
	for(int i=n;i<(n+32);i++)a[i]=0;
	n=n>>5<<5|31;int m=(n+1)>>5;
	for(int i=0;i<n;i+=32)upd(1,0,m-1,i>>5,calc(i,i|31));
	for(int i=1,op,x,y;i<=q;i++){
		cin>>op>>x>>y;--x;
		if(op==1){
			a[x]=y,upd(1,0,m-1,x>>5,calc(x>>5<<5,x|31));
		}
		else{
			ll z=0;--y;
			if((x>>5)==(y>>5)){
				for(int j=y;j>=x;--j)z=z*2+a[j];
			}
			else{
				int l=(x>>5)+1,r=(y>>5)-1;
				for(int i=y;(i>>5)!=r;--i)z=min(max(z*2+a[i],-lim),lim);
				if(l<=r){
					pii t=qry(1,0,m-1,l,r);
					if(z>t.fi)z=lim;
					else if(z<t.fi)z=-lim;
					else z=t.se;
				}
				for(int i=(l<<5)-1;i>=x;--i)z=min(max(z*2+a[i],-lim),lim);
			}
			cout<<((z<0)?-1:(z>0?1:0))<<"\n";
		}
	}
}
int main(){
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int T;cin>>T;while(T--)solve();
	return 0;
}

