#include<bits/stdc++.h>
using namespace std;
int n,m,a[500005],b[500005];
struct apple{
	int mn,om,am;
	int qz,qmn;
	int hz,hmn;
	bool fl;
}sm[2000005];
apple operator+(const apple& a,const apple& b){
	apple c;
	c.mn=min(a.mn,b.mn);c.am=max(a.am,b.am);
	c.om=max(a.mn==c.mn?a.om:a.am,b.mn==c.mn?b.om:b.am);
	if(!a.fl&&!b.fl){
		int mm=min(a.hmn,b.qmn),cd=a.hz+b.qz;
		c.am=max(c.am,cd);
		if(mm!=c.mn)c.om=max(c.om,cd);
	}
	if(!a.fl||!b.fl)c.fl=0;
	else c.fl=1;
	if(!a.fl)c.qz=a.qz,c.qmn=a.qmn;
	else c.qz=a.qz+b.qz,c.qmn=min(a.qmn,b.qmn);
	if(!b.fl)c.hz=b.hz,c.hmn=b.hmn;
	else c.hz=a.hz+b.hz,c.hmn=min(a.hmn,b.hmn);
	return c;
}
int lz[2000005];
inline void put(int o,int z){
	sm[o].mn+=z,sm[o].qmn+=z,sm[o].hmn+=z;lz[o]+=z;
}
inline void pushdown(int o){
	if(lz[o]){
		put(o<<1,lz[o]);put(o<<1|1,lz[o]);lz[o]=0;
	}
}
void su(int x,int o){
	sm[o].om=sm[o].am=0;
	if(b[x]||b[x+1])sm[o].fl=0;
	else sm[o].fl=1;
	if(b[x])sm[o].qz=0,sm[o].qmn=1e9;
	else sm[o].qz=1,sm[o].qmn=sm[o].mn;
	if(b[x+1])sm[o].hz=0,sm[o].hmn=1e9;
	else sm[o].hz=1,sm[o].hmn=sm[o].mn;
	if(b[x]&&b[x+1])sm[o].am=1;
}
void build(int l,int r,int o){
	lz[o]=0;
	if(l==r){
		sm[o].mn=0;su(l,o);return;
	}
	int mid=(l+r)>>1;
	build(l,mid,o<<1);build(mid+1,r,o<<1|1);
	sm[o]=sm[o<<1]+sm[o<<1|1];
}
void add(int l,int r,int o,int ll,int rr,int z){
	if(l>=ll&&r<=rr){
		put(o,z);return;
	}
	pushdown(o);
	int mid=(l+r)>>1;
	if(mid>=ll)add(l,mid,o<<1,ll,rr,z);
	if(mid<rr)add(mid+1,r,o<<1|1,ll,rr,z);
	sm[o]=sm[o<<1]+sm[o<<1|1];
}
void jia(int a,int b,int c){
	if(a<=b)return;
	add(1,n-1,1,b,a-1,c);
}
void reb(int l,int r,int o,int x){
	if(l==r){
		su(l,o);return;
	}
	pushdown(o);
	int mid=(l+r)>>1;
	if(x<=mid)reb(l,mid,o<<1,x);
	else reb(mid+1,r,o<<1|1,x);
	sm[o]=sm[o<<1]+sm[o<<1|1];
}
void gai(int a){
	reb(1,n-1,1,a);
}
void output(){
	int ans=(sm[1].mn==0?sm[1].om:sm[1].am);
	printf("%d\n",ans);
}
int main(){
	int T;scanf("%d",&T);
	while(T--){
		scanf("%d%d",&n,&m);
		for(int i=1;i<=n;++i)scanf("%d",&a[i]);
		if(n==1){
			int x=0,y=0;
			while(m--){
				scanf("%d%d",&x,&y);
				puts("0");
			}
			continue;
		}
		for(int i=1;i<=n;++i)++b[a[i]];
		build(1,n-1,1);
		for(int i=1;i<n;++i)jia(a[i],a[i+1],1);
		while(m--){
			int x,y;scanf("%d%d",&x,&y);
			if(x>1)jia(a[x-1],a[x],-1);
			if(x<n)jia(a[x],a[x+1],-1);
			if(!(--b[a[x]])){
				if(a[x]>1)gai(a[x]-1);
				if(a[x]<n)gai(a[x]);
			}
			a[x]=y;
			if(!(b[a[x]]++)){
				if(a[x]>1)gai(a[x]-1);
				if(a[x]<n)gai(a[x]);
			}
			if(x>1)jia(a[x-1],a[x],1);
			if(x<n)jia(a[x],a[x+1],1);
			output();
		}
		for(int i=1;i<=n;++i)b[i]=0;
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std; using ll=long long;
const int N=1e6+5;
int n;ll A[N],B[N];
void Solve(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++) scanf("%lld",&A[i]),scanf("%lld",&B[i]);
	ll g1=0,g2=0;
	for(int i=1;i<n;i++) g1=__gcd(g1,abs(A[i]-A[i+1]));
	for(int i=1;i<n;i++) g2=__gcd(g2,abs(B[i]-B[i+1]));
	if(g1^g2){
		puts("No");
		return;
	}
	int g=g1*2;
	if(!g){
		puts(A[1]==B[1]?"Yes":"No");
		return;
	}
