			mx[x0].erase(it);
			if(vis[id]) continue;
			vis[id]=true;
			pos.push_back(sum+abs(y-y0));
		}
	}else if(y0==y1){
		ll l=x0,r=x1;
		if(l>r) swap(l,r);
