}

vec solve(vec a, vec b, vec c) {
  bool fa = a.empty(), fb = b.empty(), fc = c.empty();
  if (fa && fb && fc) return {};
  if (fa && fb) return c;
  if (fa && fc) return b;
  if (fb && fc) return a;
  if (fa) return {c[0], b[0]};
  if (fb) return {a[0], c[0]};
  if (fc) return {b[0], a[0]};
  vec la, ra, lb, rb, lc, rc, ls, rs, res;
  int u = a[get(0, a.size() - 1)];
  for (int x : b)
    if (query(u, x) == 1) lb.push_back(x);
    else rb.push_back(x);
  for (int x : c)
    if (query(u, x) == 1) rc.push_back(x);
    else lc.push_back(x);
  if (rc.empty()) { for (int x : a) if (x != u) la.push_back(x); }
  else {
    auto v = rc.begin();
    for (int x : rb) while (query(x, *v) == 2) ++v;
    for (int x : a) if (x != u) {
      if (query(x, *v) == 1) la.push_back(x);
      else ra.push_back(x);
    }
  }
  ls = solve(la, lb, lc), rs = solve(ra, rb, rc);
  for (int x : ls) res.push_back(x);
  res.push_back(u);
  for (int x : rs) res.push_back(x);
  return res;
}

