using namespace std;
const int N=3e6+10,mod=998244353;
const int G=3,inv2=499122177;
int qpow(int x,int y=mod-2){
	int m=1;
	for(;y;y>>=1,x=1ll*x*x%mod)if(y&1)m=1ll*m*x%mod;
	return m; 
}
int tr[N];
void calrev(int n){
	for(int i=0;i<n;i++)tr[i]=((tr[i>>1]>>1)|((i&1)?(n>>1):0));
}
#define clr(f,n) memset(f,0,sizeof(int)*(n))
#define cpy(f,g,n) memcpy(f,g,sizeof(int)*(n))
int P[N],iv[N];
int inv[N];
void init(int n){
	for(int i=1,j=2;j<=n;++i,j<<=1){
		P[i]=qpow(G,(mod-1)/j);
		iv[i]=qpow(P[i]);
	}
	inv[1]=1;
	for(int i=2;i<=n;++i)inv[i]=1ll*inv[mod%i]*(mod-mod/i)%mod;
}
void NTT(int *f,int n,bool flg){
	calrev(n);
	for(int i=0;i<n;i++)if(i<tr[i])swap(f[tr[i]],f[i]);
	for(int q=2,i=1;q<=n;q<<=1,++i){
		int len=q>>1;
		int Yg=flg?P[i]:iv[i];
		for(int k=0;k<n;k+=q){
			int buf=1;
			for(int j=k;j<k+len;j++){
				int tt=1ll*f[j+len]*buf%mod;
				f[j+len]=(f[j]-tt+mod)%mod;
				f[j]=(f[j]+tt)%mod;
				buf=1ll*buf*Yg%mod;
			}
		}
	}
	if(!flg){
		int invn=qpow(n);
		for(int i=0;i<n;i++)f[i]=1ll*f[i]*invn%mod;
	}
}
void Mul(int *f,int *g,int len,int lim){
//	for(int i=len-1;i>=0;i--){
//		f[i]=1ll*f[i]*g[0]%mod;
//		for(int j=1;j<=i;j++)f[i]=(f[i]+1ll*g[j]*f[i-j])%mod;
//	}
//	return;
	static int sav[N];
	int n=1;for(;n<=len+len;n<<=1);
	cpy(sav,g,n);
	NTT(f,n,1);NTT(sav,n,1);
	for(int i=0;i<n;i++)f[i]=1ll*f[i]*sav[i]%mod;
	NTT(f,n,0);
	clr(f+lim,n-lim);clr(sav,n);
}
void invp(int *f,int m){
	static int w[N],r[N],sav[N];
	int n=1;for(;n<=m;n<<=1);
	w[0]=qpow(f[0]);
	for(int len=2;len<=n;len<<=1){
		for(int i=0;i<(len>>1);i++)r[i]=(w[i]<<1)%mod;
		cpy(sav,f,len);
		NTT(w,len<<1,1);NTT(sav,len<<1,1);
		for(int i=0;i<(len<<1);i++)w[i]=1ll*w[i]*w[i]%mod*sav[i]%mod;
		NTT(w,len<<1,0);clr(w+len,len);
		for(int i=0;i<len;i++)w[i]=(r[i]-w[i]+mod)%mod;
	}
	cpy(f,w,m+1);clr(sav,n+n);clr(w,n+n);clr(r,n+n);
}
