struct segtree
{
	int ax[N*4],sm[N*4],lzy[N*4];
	void u(int l,int r,int rt,int c)
	{
		ax[rt]+=c;sm[rt]+=(r-l+1)*c;lzy[rt]+=c;
	}
	void up(int rt)
	{
		ax[rt]=max(ax[rt<<1],ax[rt<<1|1]);
		sm[rt]=sm[rt<<1]+sm[rt<<1|1];
	}
	void down(int l,int r,int rt){int m=(l+r)>>1;u(lson,lzy[rt]);u(rson,lzy[rt]);lzy[rt]=0;}
	void add(int a,int b,int c,int l,int r,int rt)
	{
		if(a<=l&&r<=b)
		{
			u(l,r,rt,c);
			return;
		}
		down(l,r,rt);int m=(l+r)>>1;
		if(a<=m)add(a,b,c,lson);
		if(b>m)add(a,b,c,rson);
		up(rt);
	}
	int qsm(int a,int b,int l,int r,int rt)
	{
		if(a<=l&&r<=b)return sm[rt];
		down(l,r,rt);int m=(l+r)>>1,ans=0;
		if(a<=m)ans=qsm(a,b,lson);
		if(b>m)ans+=qsm(a,b,rson);
		return ans;
	}
	int qax(int a,int b,int l,int r,int rt)
	{
		if(a<=l&&r<=b)return ax[rt];
		down(l,r,rt);int m=(l+r)>>1,ans=-N;
		if(a<=m)ans=qax(a,b,lson);
		if(b>m)ans=max(ans,qax(a,b,rson));
		return ans;
	}
