void getvec(int u,int dep,vector<int>&tmp) {
	tmp.clear();
	static set<node>::iterator it;
	it=st[dep].lower_bound({id[u],u});
	while(it!=st[dep].end()) {
		if((*it).x<id[u]+siz[u]) {
			tmp.push_back(it->y);
			it=st[dep].erase(it);
		} else break;
	}
}
void dfs(int u) {
	id[u]=++tid;
	siz[u]=1;
	st[dep[u]].insert(node {id[u],u});
	if(vec[u].empty()) return;
	for(int v:vec[u]) dfs(v),siz[u]+=siz[v];
	for(int&d:tmp[u]) {
		d+=dep[u];
		vector<int>tt;
		getvec(u,d,tt);
		if(tt.size()>=2) {
			++tcnt;
			for(int x:tt) {
				id[tcnt]=id[x];
				e[pos(x)].push_back(pos(tcnt));
				e[neg(tcnt)].push_back(neg(x));
			}
			tt.clear(),tt.shrink_to_fit();
			tt.push_back(tcnt);
		}
		for(int x:tt) {
			e[pos(x)].push_back(neg(u));
			e[pos(u)].push_back(neg(x));
			st[d].insert(node {id[x],x});
		}
		tt.clear(),tt.shrink_to_fit();
	}
}
void tarjan(int u) {
	dfn[u]=low[u]=++tot;
	sta[++top]=u;
	vis[u]=true;
	for(int v:e[u]) {
		if(!dfn[v]) {
			tarjan(v);
			low[u]=min(low[u],low[v]);
		} else if(vis[v])
			low[u]=min(low[u],dfn[v]);
	}
	if(low[u]==dfn[u]) {
		++gcnt;
		do {
			vis[sta[top]]=false;
			grp[sta[top]]=gcnt;
		} while(sta[top--]^u);
	}
}
