int F[N], IF[N], G[N];
int R(int x, int y) { return (x += y) >= MOD ? x - MOD : x; }
int qpow(int x, int y) {
	int t = 1;
	for (; y; y>>=1) {
		if (y & 1) t = 1ll * t * x % MOD;
		x = 1ll * x * x % MOD;
	} return t;
}
int C(int n, int k) { return 1ll * F[n] * IF[k] % MOD * IF[n-k] % MOD; }
void NTT(int n, int *a, bool o) {
	for (int i=0; i<n; i++)
		if (i < p[i])
			swap(a[i], a[p[i]]);
	for (int i=1; i<n; i<<=1)
		for (int j=0; j<n; j+=i<<1)
			for (int k=j; k<j+i; k++) {
				int _ = 1ll * G[i+k-j] * a[k+i] % MOD;
				a[k+i] = R(a[k], MOD - _), a[k] = R(a[k], _);
			}
	if (o) {
		reverse (a+1, a+n);
		int inv = qpow(n, MOD - 2);
		for (int i=0; i<n; i++)
			a[i] = 1ll * a[i] * inv % MOD;
	}
}
void polymul(int n, int *a, int m, int *b, int l, int *c) {
	int len = 1;
	while (len < n + m - 1) len <<= 1;
	for (int i=0; i<len; i++)
		ta[i] = i < n ? a[i] : 0, tb[i] = i < m ? b[i] : 0, p[i] = p[i>>1] >> 1 | (i & 1 ? len >> 1 : 0);
	NTT(len, ta, 0), NTT(len, tb, 0);
	for (int i=0; i<len; i++)
		ta[i] = 1ll * ta[i] * tb[i] % MOD;
	NTT(len, ta, 1);
	for (int i=0; i<l; i++)
		c[i] = ta[i];
}
void solve(int l, int r) {
	if (l == r) {
		for (int y=h[l]+1; y<=h[l+1]; y++)
			g[y] = f[l];
		return ;
	}
	int mid = l + r >> 1;
	// cerr << l << '-' << r << endl;
	// for (int i=l; i<=r; i++)
		// cerr << "x = " << i << " : " << f[i] << endl;
	solve(l, mid);
	if (h[mid+1] == h[l]) {
		for (int x=mid+1; x<=r; x++)
			tf[x] = f[x];
	} else {
		for (int i=0; i<=r-mid-1; i++)
			coef[i] = C(i + h[mid+1] - h[l] - 1, i);
		polymul(r - mid, coef, r - mid, f + mid + 1, r - mid, tf + mid + 1);
		for (int i=0; i<=r-mid-1+h[mid+1]-h[l]-1; i++)
			coef[i] = F[i];
		for (int i=0; i<=h[mid+1]-h[l]-1; i++)
			tmp[i] = 1ll * IF[h[mid+1]-h[l]-1-i] * g[h[l]+1+i] % MOD;
		polymul(r - mid + h[mid+1] - h[l] - 1, coef, h[mid+1] - h[l], tmp, r - mid + h[mid+1] - h[l] - 1, tmp);
		for (int i=0; i<=r-mid-1; i++)
			tf[mid+1+i] = (tf[mid+1+i] + 1ll * IF[i] * tmp[h[mid+1]-h[l]-1+i]) % MOD;
		for (int i=0; i<=h[mid+1]-h[l]-1; i++)
			coef[i] = C(r - mid - 1 + i, r - mid - 1);
		polymul(h[mid+1] - h[l], coef, h[mid+1] - h[l], g + h[l] + 1, h[mid+1] - h[l], tg + h[l] + 1);
		for (int i=0; i<=r-mid-1+h[mid+1]-h[l]-1; i++)
			coef[i] = F[i];
		for (int i=0; i<=r-mid-1; i++)
			tmp[i] = 1ll * IF[r-mid-1-i] * f[mid+1+i] % MOD;
		polymul(r - mid + h[mid+1] - h[l] - 1, coef, r - mid, tmp, r - mid + h[mid+1] - h[l] - 1, tmp);
		for (int i=0; i<=h[mid+1]-h[l]-1; i++)
			tg[h[l]+1+i] = (tg[h[l]+1+i] + 1ll * IF[i] * tmp[r-mid-1+i]) % MOD;
	}
	for (int x=mid+1; x<=r; x++)
		f[x] = tf[x];
	for (int y=h[l]+1; y<=h[mid+1]; y++)
		g[y] = tg[y];
	solve(mid + 1, r);
	// cerr << l << '-' << r << endl;
	// for (int i=h[l]+1; i<=h[r+1]; i++)
		// cerr << "y = " << i << " : " << g[i] << endl;
}
