#include <bits/stdc++.h>
using ll = long long;
using i128 = __int128_t;
constexpr int N = 500 + 2;
int n; ll m; ll a[N];
inline int nxt(int x) { return x == n - 1 ? 0 : (x + 1); }
inline int pre(int x) { return x == 0 ? (n - 1) : (x - 1); }
int qmx[N], hmx, tmx;
int qmn[N], hmn, tmn;
inline void pop(int i) {
  hmx = qmx[hmx] == i ? nxt(hmx) : hmx;
  hmn = qmn[hmn] == i ? nxt(hmn) : hmn;
}
inline void push(int i) {
  while (tmx != pre(hmx) && a[qmx[tmx]] <= a[i]) tmx = pre(tmx);
  qmx[tmx = nxt(tmx)] = i;
  while (tmn != pre(hmn) && a[qmn[tmn]] >= a[i]) tmn = pre(tmn);
  qmn[tmn = nxt(tmn)] = i;
}
inline void solve(int tt) {
  scanf("%d%lld", &n, &m), m--;
  for (int i = 0; i < n; i++)
    scanf("%lld", &a[i]);
  if (m < n)
    return printf("%lld\n", a[m]), void();
  m -= n - 1;
  hmx = hmn = 0, tmx = tmn = n - 1;
  for (int i = 0; i < n; i++)
    push(i);
  for (int p = 0; ; p = nxt(p)) {
    a[p] = a[qmx[hmx]] - a[qmn[hmn]];
    if (--m == 0)
      return printf("%lld\n", a[p]), void();
    pop(p), push(p);
    if (a[pre(p)] > (i128)a[p] * (n + 1)) {
      bool chk = true;
      for (int i = nxt(p); chk && i != p; i = nxt(i))
        chk &= a[i] >= a[nxt(i)];
      if (! chk)
        continue;
      ll v = a[p];
      ll lim = std::min(v == 0 ? (ll)1e18 : ((a[pre(p)] - v - 1) / (v * n)), (m - 1) / ((n + 1) * (n - 1)));
      m -= lim * (n + 1) * (n - 1);
      for (int i = nxt(p); i != p; i = nxt(i))
        a[i] -= lim * v * n;
    }
  }
}
int main() {
  int t;
  scanf("%d", &t);
  for (int tt = 1; tt <= t; tt++)
    solve(tt);
  return 0;
}

