constexpr int N = 10, M = 9;
constexpr int dx[12] = {+1, -1, +1, -1, +2, -2, +2, -2, +1, -1,  0,  0};
constexpr int dy[12] = {+2, -2, -2, +2, +1, -1, -1, +1,  0,  0, +1, -1};
// M: 0~7, C: 8~11
inline bool inside(int x, int y) {
  return 0 <= x && x < N && 0 <= y && y < M;
}
char map[N + 2][M + 2];
int cM, cC;
bool ban[N][M];
int dis[N][N], pre[N][N];
void bfs(int sx, int sy) {
  std::queue<std::pair<int, int>> Q;
  memset(dis, -1, sizeof(dis));
  pre[sx][sy] = -1, dis[sx][sy] = 0, Q.emplace(sx, sy);
  while (! Q.empty()) {
    auto [x, y] = Q.front(); Q.pop();
    if (ban[x][y]) continue;
    for (int d = 0; d < (cC ? 12 : 8); d++) {
      int tx = x + dx[d], ty = y + dy[d];
      if (inside(tx, ty) && dis[tx][ty] == -1)
        dis[tx][ty] = dis[tx][ty] + 1, pre[tx][ty] = d ^ 1, Q.emplace(tx, ty);
    }
  }
}
std::vector<std::tuple<int, int, int, int>> op;
inline void solve(int sx, int sy, std::vector<std::pair<int, int>> Ban) {
  bfs(sx, sy);
  int tx = -1, ty = -1;
  for (int i = 0; i < N; i++)
    for (int j = 0; j < M; j++)
      if ((map[i][j] == 'M' || map[i][j] == 'C') && dis[i][j] != -1 && std::find(Ban.begin(), Ban.end(), std::make_pair(i, j)) == Ban.end())
        tx = i, ty = j;
  int ax = -1, ay = -1;
  for (int i = 0; i < N; i++)
    for (int j = 0; j < M; j++)
      if ((map[i][j] == 'M' || map[i][j] == 'C') && map[i][j] != map[tx][ty])
        ax = i, ay = j;
  while (tx != sx || ty != sy) {
    int d = pre[tx][ty];
    if ((d < 8 && map[tx][ty] == 'C') || (d >= 8 && map[tx][ty] == 'M'))
      op.emplace_back(tx, ty, ax, ay), std::swap(map[tx][ty], map[ax][ay]);
    op.emplace_back(tx, ty, tx + dx[d], ty + dy[d]);
    std::swap(map[tx][ty], map[tx + dx[d]][ty + dy[d]]);
    tx += dx[d], ty += dy[d];
  }
}
