	if (it != pos.begin()) {
		auto j = *prev(it);
		ins(j, i, -1);
	}
	if (next(it) != pos.end()) {
		auto j = *next(it);
		ins(i, j, -1);
	}
	if (it != pos.begin() && next(it) != pos.end()) {
		ins(*prev(it), *next(it), 1);
	}
	pos.erase(it);
}
