				{
					while(qi<cnt&&QI[qi]<j)col[c]|=vis[i]&msk,msk<<=W,qi++;
					c=Y[j];
				}
				while(qi<cnt)col[c]|=vis[i]&msk,msk<<=W,qi++;
				CH[i]=false;
				ch[i].clear();
			}
		}
		int ans[Z]={};
		for(int i=0;i<N;)
		{
			int r=min(i+(1<<W)-1,N);
			unsigned long long sum=0;
			for(int j=i;j<r;j++)sum+=col[j];
			i=r;
			for(int k=0;k<cnt;k++)ans[k]+=sum&(1<<W)-1,sum>>=W;
		}
		for(int i=0;i<cnt;i++)cout<<ans[i]<<"\n";
		for(int q=l;q<r;q++)if(op[q]==1)A[X[q]]=Y[q];
		l=r;
	}
}

